def _bm23_load_theme_pref():
    """Return the persisted reactor theme name or 'cyan_nebula' by default."""
    try:
        p = Path.home() / '.email_archive' / 'reactor_theme.json'
        if p.exists():
            d = json.loads(p.read_text(encoding='utf-8'))
            name = d.get('theme')
            if name in _BM23_REACTOR_THEMES:
                return name
    except Exception:
        pass
    return 'cyan_nebula'


def _bm23_save_theme_pref(name):
    try:
        p = Path.home() / '.email_archive' / 'reactor_theme.json'
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(json.dumps({'theme': name}), encoding='utf-8')
        return True
    except Exception:
        return False


# Back-compat alias used by earlier helper.
_BM23_REACTOR_HTML = _BM23_REACTOR_THEMES['cyan_nebula']


class _BM23ReactorBackground(QWidget if False else object):
    """Placeholder — real class defined after PyQt6 imports resolve below.
    Injected into main window via _bm23_install_reactor()."""
    pass


def _bm23_install_reactor(mainwin, theme=None):
    """Attach a full-window reactor QWebEngineView behind mainwin's central
    widget. Theme = key in _BM23_REACTOR_THEMES (default: persisted pref).
    Silently no-ops when WebEngine unavailable."""
    if not _BM23_WEBENGINE or QWebEngineView is None:
        return None
    theme = theme or _bm23_load_theme_pref()
    if theme not in _BM23_REACTOR_THEMES:
        theme = 'cyan_nebula'
    try:
        from PyQt6.QtCore import QUrl as _QUrl
        from PyQt6.QtWidgets import QWidget as _QW
        class _Reactor(_QW):
            def __init__(self, parent):
                super().__init__(parent)
                self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
                self.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, False)
                self.view = QWebEngineView(self)
                s = self.view.settings()
                s.setAttribute(QWebEngineSettings.WebAttribute.JavascriptEnabled, True)
                s.setAttribute(QWebEngineSettings.WebAttribute.WebGLEnabled, True)
                s.setAttribute(QWebEngineSettings.WebAttribute.Accelerated2dCanvasEnabled, True)
                try:
                    from PyQt6.QtGui import QColor as _QC
                    self.view.page().setBackgroundColor(_QC(2, 2, 10, 255))
                except Exception:
                    pass
                self.current_theme = theme
                self.view.setHtml(_BM23_REACTOR_THEMES[theme], _QUrl('https://sift.local/'))
                self.view.setGeometry(0, 0, parent.width(), parent.height())
            def resizeEvent(self, e):
                self.view.setGeometry(0, 0, self.width(), self.height())
                super().resizeEvent(e)
            def apply_theme(self, name):
                if name not in _BM23_REACTOR_THEMES:
                    return False
                self.current_theme = name
                try:
                    self.view.setHtml(_BM23_REACTOR_THEMES[name], _QUrl('https://sift.local/'))
                    _bm23_save_theme_pref(name)
                    return True
                except Exception:
                    traceback.print_exc()
                    return False
        reactor = _Reactor(mainwin)
        reactor.setGeometry(0, 0, mainwin.width(), mainwin.height())
        reactor.lower()
        reactor.show()
        mainwin._bm23_reactor = reactor
        _orig_resize = getattr(mainwin, 'resizeEvent', None)
        def _resize(e):
            try:
                reactor.setGeometry(0, 0, mainwin.width(), mainwin.height())
            except Exception:
                pass
            if _orig_resize is not None:
                _orig_resize(e)
        mainwin.resizeEvent = _resize
        try:
            cw = mainwin.centralWidget()
            if cw:
                cw.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, False)
                cw.setAutoFillBackground(False)
        except Exception:
            pass
        return reactor
    except Exception:
        traceback.print_exc()
        return None


def _bm23_switch_reactor_theme(mainwin, name):
    """External hook — swap the live reactor's theme + persist choice."""
    reactor = getattr(mainwin, '_bm23_reactor', None)
    if reactor is None:
        return False
    return reactor.apply_theme(name)


# ============================================================================
# FULL WEB GUI TAKEOVER — kills the legacy PyQt panels + replaces the main
# window's central widget with a single QWebEngineView loading the SIFT web UI.
# Old panel code stays in the module for later hookup but never gets shown.
# ============================================================================



def _bm23_go_full_web(mainwin):
    """Nuke the legacy PyQt central widget. Replace with a single full-screen
    QWebEngineView loading the SIFT web GUI. Backend code stays intact for
    future JS bridge hookup. Silent no-op when WebEngine unavailable."""
    if not _BM23_WEBENGINE or QWebEngineView is None:
        return False
    try:
        from PyQt6.QtCore import QUrl as _QUrl
        # Kill any previous reactor overlay first
        try:
            r = getattr(mainwin, '_bm23_reactor', None)
            if r is not None:
                r.hide(); r.deleteLater()
        except Exception:
            pass
        view = QWebEngineView(mainwin)
        s = view.settings()
        s.setAttribute(QWebEngineSettings.WebAttribute.JavascriptEnabled, True)
        s.setAttribute(QWebEngineSettings.WebAttribute.WebGLEnabled, True)
        s.setAttribute(QWebEngineSettings.WebAttribute.Accelerated2dCanvasEnabled, True)
        s.setAttribute(QWebEngineSettings.WebAttribute.LocalStorageEnabled, True)
        try:
            from PyQt6.QtGui import QColor as _QC
            view.page().setBackgroundColor(_QC(2, 2, 10, 255))
        except Exception:
            pass
        view.setHtml(_BM23_FULL_WEB_HTML, _QUrl('https://sift.local/'))
        mainwin.setCentralWidget(view)
        mainwin._bm23_web = view
        return True
    except Exception:
        traceback.print_exc()
        return False


# ============================================================================
# LOST-EMAIL INVESTMENTS / REDEMPTION-CODES SCANNER
# ----------------------------------------------------------------------------
# Massive regex covers: BTC/LTC WIF keys, seed phrases (BIP39), BIP32 xprv/xpub,
# JWTs, OAuth tokens (Google/GitHub/Slack/Discord/AWS/Stripe/Google API),
# PEM + SSH + PGP key blocks, Ethereum/Solana/XRP/BTC addresses, generic hex
# 32/40/64/128, IPs/CIDR/IPv6, Azure SAS tokens, IMEI, complex passwords,
# generic base64 blobs.
#
# WARNING: some branches (bare base64/hex/IP/3+ lowercase words) are broad and
# will hit false positives. Downstream UI (next rev) is expected to bucket
# matches by kind + let the user triage. Do NOT auto-act on these matches.
# ============================================================================

_BM23_SECRET_REGEX_SRC = (
    r'(?i)(?:'
    r'\b[5KL][1-9A-HJ-NP-Za-km-z]{50,51}\b'                                 # BTC/LTC WIF
    r'|\b[0-9a-fA-F]{64}\b'                                                  # generic 64-hex
    r'|\b(?:xprv|xpub|yprv|ypub|zprv|zpub)[1-9A-HJ-NP-Za-km-z]{78,112}\b'    # BIP32 ext keys
    r'|\b(?:[a-z]+(?:\s+)){11,23}[a-z]+\b'                                    # BIP39 seed phrase (12-24 words)
    r'|\b(?:[0-9a-fA-F]{32}|[0-9a-fA-F]{64}|[0-9a-fA-F]{128})\b'              # hex 32/64/128
    r'|\b[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\b'                    # JWT
    r'|\b(?:ya29\.[0-9A-Za-z_-]{20,200}|gho_[0-9A-Za-z]{36,255}'
    r'|ghs_[0-9A-Za-z]{36,255}|ghu_[0-9A-Za-z]{36,255})\b'                    # Google/GH tokens
    r'|\bAKIA[0-9A-Z]{16}\b'                                                  # AWS access key id
    r'|AIza[0-9A-Za-z\-_]{35}'                                                # Google API key
    r'|\bsk_live_[0-9A-Za-z]{24,99}\b'                                        # Stripe live
    r'|-----BEGIN (?:RSA|EC|DSA|OPENSSH|PRIVATE|PUBLIC) KEY-----[\s\S]+?'
    r'-----END (?:RSA|EC|DSA|OPENSSH|PRIVATE|PUBLIC) KEY-----'                # PEM block
    r'|\bssh-(?:rsa|ed25519|dss) [A-Za-z0-9+/=]{50,2000}(?: .*)?\b'           # SSH pubkey line
    r'|-----BEGIN PGP (?:PUBLIC|PRIVATE) KEY BLOCK-----[\s\S]+?'
    r'-----END PGP (?:PUBLIC|PRIVATE) KEY BLOCK-----'                         # PGP block
    r'|\b(?:[0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2}\b'                              # MAC address
    r'|\b\d{15}\b'                                                            # IMEI
    r'|\b[0-9a-fA-F]{40}\b'                                                   # SHA-1 hex / eth-priv-len
    r'|\b[0-9A-Za-z/+]{40}\b'                                                 # generic 40-b64ish
    r'|\bsv=[0-9A-Za-z%]+&sig=[0-9A-Za-z%]+(?:&spr=https?)?\b'                # Azure SAS
    r'|\b1\/[A-Za-z0-9_-]{50,200}\b'                                          # Google OAuth 1/
    r'|\bxox[baprs]-[0-9A-Za-z-]{10,50}\b'                                    # Slack token
    r'|\b[0-9]{17,19}\.[A-Za-z0-9_-]{6,10}\.[A-Za-z0-9_-]{27,40}\b'           # Discord bot
    r'|\b0x[0-9a-fA-F]{40}\b'                                                 # Ethereum address
    r'|\b[1-9A-HJ-NP-Za-km-z]{87,88}\b'                                       # Solana pubkey
    r'|\b[1-9A-HJ-NP-Za-km-z]{32,44}\b'                                       # BTC base58 addr
    r'|\bs[a-zA-Z0-9]{28,35}\b'                                               # XRP secret
    r'|\b[A-Za-z0-9+/]{32,512}={0,2}\b'                                       # generic base64
    r'|\b(?=.*[A-Z])(?=.*[a-z])(?=.*\d)(?=.*[_\-])[A-Za-z0-9_\-]{20,200}\b'   # complex mixed-case token
    r'|\b(?=.*[A-Z])(?=.*[a-z])(?=.*\d)[A-Za-z0-9!@#$%^&*()_+\-=]{8,64}\b'    # strong password
    r'|\b(?:\d{1,3}\.){3}\d{1,3}\b'                                           # IPv4
    r'|\b(?:[0-9A-Fa-f]{1,4}:){7}[0-9A-Fa-f]{1,4}\b'                          # IPv6
    r'|\b(?:\d{1,3}\.){3}\d{1,3}\/(?:[0-9]|[12][0-9]|3[0-2])\b'               # CIDR
    r')'
)

try:
    _BM23_SECRET_REGEX = re.compile(_BM23_SECRET_REGEX_SRC)
except Exception:
    _BM23_SECRET_REGEX = None


def _bm23_classify_secret(match_text):
    """Cheap kind-label so downstream UI can bucket hits.
    Returns one of: 'btc-wif', 'bip32', 'seed', 'jwt', 'google-oauth',
    'github-token', 'aws-key', 'google-api', 'stripe-key', 'pem-key',
    'ssh-key', 'pgp-key', 'slack-token', 'discord-token', 'eth-address',
    'solana-key', 'xrp-secret', 'azure-sas', 'sha256-hex', 'sha1-hex',
    'hex-blob', 'base64-blob', 'mac-addr', 'imei', 'ipv4', 'ipv6', 'cidr',
    'strong-password', 'unknown'."""
    if not match_text:
        return 'unknown'
    s = match_text.strip()
    sl = s.lower()
    if s.startswith(('5', 'K', 'L')) and re.match(r'^[5KL][1-9A-HJ-NP-Za-km-z]{50,51}$', s):
        return 'btc-wif'
    if sl.startswith(('xprv', 'xpub', 'yprv', 'ypub', 'zprv', 'zpub')):
        return 'bip32'
    if ' ' in s and re.match(r'^(?:[a-z]+(?:\s+)){11,23}[a-z]+$', s):
        return 'seed'
    if s.count('.') == 2 and re.match(r'^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$', s):
        return 'jwt'
    if sl.startswith('ya29.'):
        return 'google-oauth'
    if sl.startswith(('gho_', 'ghs_', 'ghu_')):
        return 'github-token'
    if s.startswith('AKIA'):
        return 'aws-key'
    if s.startswith('AIza'):
        return 'google-api'
    if s.startswith('sk_live_'):
        return 'stripe-key'
    if 'BEGIN' in s and 'KEY' in s:
        return 'pgp-key' if 'PGP' in s else 'pem-key'
    if s.startswith(('ssh-rsa ', 'ssh-ed25519 ', 'ssh-dss ')):
        return 'ssh-key'
    if sl.startswith('xox') and '-' in s:
        return 'slack-token'
    if s.startswith('0x') and re.match(r'^0x[0-9a-fA-F]{40}$', s):
        return 'eth-address'
    if re.match(r'^s[a-zA-Z0-9]{28,35}$', s):
        return 'xrp-secret'
    if 'sv=' in sl and '&sig=' in sl:
        return 'azure-sas'
    if re.match(r'^(?:[0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2}$', s):
        return 'mac-addr'
    if re.match(r'^(?:\d{1,3}\.){3}\d{1,3}$', s):
        return 'ipv4'
    if re.match(r'^(?:\d{1,3}\.){3}\d{1,3}/(?:[0-9]|[12][0-9]|3[0-2])$', s):
        return 'cidr'
    if re.match(r'^(?:[0-9A-Fa-f]{1,4}:){7}[0-9A-Fa-f]{1,4}$', s):
        return 'ipv6'
    if re.match(r'^\d{15}$', s):
        return 'imei'
    if re.match(r'^[0-9a-fA-F]{64}$', s):
        return 'sha256-hex'
    if re.match(r'^[0-9a-fA-F]{40}$', s):
        return 'sha1-hex'
    if re.match(r'^[0-9a-fA-F]{32,128}$', s):
        return 'hex-blob'
    if re.match(r'^[1-9A-HJ-NP-Za-km-z]{87,88}$', s):
        return 'solana-key'
    if re.match(r'^[1-9A-HJ-NP-Za-km-z]{32,44}$', s):
        return 'btc-address'
    if re.match(r'^[A-Za-z0-9+/]{32,512}={0,2}$', s):
        return 'base64-blob'
    if re.search(r'\d', s) and re.search(r'[A-Z]', s) and re.search(r'[a-z]', s):
        return 'strong-password'
    return 'unknown'


def _bm23_scan_email_for_secrets(html_body, text_body='', dedupe=True, max_matches=200):
    """Scan a single email body (HTML + optional plaintext) for high-value
    secrets, seed phrases, private keys, tokens, addresses.

    Returns a list of {'kind': str, 'text': str, 'span': (int,int), 'source': 'html'|'text'}.
    Deduplicates identical matches when dedupe=True. Capped at max_matches.

    NOT wired to UI in this rev — call from the reader pane or a batch scanner
    once we've built the results dialog."""
    if _BM23_SECRET_REGEX is None:
        return []
    seen = set()
    hits = []
    for source_name, body in (('html', html_body or ''), ('text', text_body or '')):
        if not body:
            continue
        # Strip HTML tags first to avoid matching URL-encoded fragments inside <img src=...>
        if source_name == 'html':
            stripped = re.sub(r'<[^>]+>', ' ', body)
        else:
            stripped = body
        for m in _BM23_SECRET_REGEX.finditer(stripped):
            txt = m.group(0)
            if dedupe:
                key = txt
                if key in seen:
                    continue
                seen.add(key)
            kind = _bm23_classify_secret(txt)
            hits.append({'kind': kind, 'text': txt, 'span': (m.start(), m.end()), 'source': source_name})
            if len(hits) >= max_matches:
                return hits
    return hits


