_BM23_VENDOR_INDEX = None

def _bm23_vendor_index():
    """Lazily build a lowercased alias-lookup dict once."""
    global _BM23_VENDOR_INDEX
    if _BM23_VENDOR_INDEX is None:
        idx = []
        for name, cat, aliases in _BM23_VENDOR_LIST:
            for a in aliases:
                idx.append((a.lower(), name, cat))
        _BM23_VENDOR_INDEX = idx
    return _BM23_VENDOR_INDEX


def _bm23_scan_email_for_vendors(subject='', html_body='', text_body='',
                                  enabled_vendors=None, max_matches=100):
    """Scan a single email for vendor/receipt/redemption references.

    Returns [{vendor, category, alias, source, context}] where source is one of
    'subject' / 'html' / 'text' and context is a ~80-char slice around the match.

    enabled_vendors: optional set/list of vendor display_name — when supplied,
    only those vendors are scanned. None = all."""
    def _norm(s):
        return _bm23_coerce_str(s, '').lower()

    subject_l = _norm(subject)
    html_l = _norm(html_body)
    # Strip HTML tags for cleaner context extraction
    html_stripped = re.sub(r'<[^>]+>', ' ', html_l) if html_l else ''
    text_l = _norm(text_body)

    hits = []
    seen = set()  # (vendor, source) — dedupe per source
    enabled = set(enabled_vendors) if enabled_vendors else None
    for alias, name, cat in _bm23_vendor_index():
        if enabled and name not in enabled:
            continue
        for source_name, body in (('subject', subject_l), ('html', html_stripped), ('text', text_l)):
            if not body:
                continue
            pos = body.find(alias)
            if pos < 0:
                continue
            key = (name, source_name)
            if key in seen:
                continue
            seen.add(key)
            ctx_start = max(0, pos - 40)
            ctx_end = min(len(body), pos + len(alias) + 40)
            ctx = body[ctx_start:ctx_end].replace('\n', ' ')
            hits.append({
                'vendor': name, 'category': cat, 'alias': alias,
                'source': source_name, 'context': '…' + ctx + '…',
            })
            if len(hits) >= max_matches:
                return hits
    return hits


def _bm23_load_vendor_prefs(app_dir=None):
    """Load user's enabled-vendor checkbox state. Returns set of names or None
    (None = all enabled by default)."""
    try:
        p = (Path(app_dir) if app_dir else Path.home() / '.email_archive') / 'vendor_prefs.json'
        if not p.exists():
            return None
        data = json.loads(p.read_text(encoding='utf-8'))
        if isinstance(data, dict) and isinstance(data.get('enabled'), list):
            return set(data['enabled'])
    except Exception:
        pass
    return None


def _bm23_save_vendor_prefs(enabled_set, app_dir=None):
    try:
        p = (Path(app_dir) if app_dir else Path.home() / '.email_archive') / 'vendor_prefs.json'
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(json.dumps({'enabled': sorted(enabled_set or [])}), encoding='utf-8')
        return True
    except Exception:
        return False


