def _bm23_inline_cid_attachments(html_content, email, token, cid_header, item_id, _coerce=True):
    if _coerce:
        # Guard against dict/None/bytes reaching the regex layer.
        # Some upstream code paths pass the whole message-body dict rather than the string.
        html_content = _bm23_coerce_str(html_content, '') if '_bm23_coerce_str' in globals() else (html_content if isinstance(html_content, str) else '')
    return _bm23_inline_cid_attachments_impl(html_content, email, token, cid_header, item_id)


def _bm23_inline_cid_attachments_impl(html_content, email, token, cid_header, item_id):
    """Replace <img src="cid:...">-style references with base64 data URIs.

    Outlook stores inline images (logos, embedded screenshots) as attachments
    with a `ContentId` header + `IsInline=true`. HTML body references them via
    `src="cid:{ContentId}"`. WebEngine (and browsers in general) cannot resolve
    the cid: scheme, so we fetch each inline attachment, base64-encode it, and
    inline the bytes as a data: URI so the image renders 1:1 with what the
    original client would show.

    Returns transformed HTML; safe no-op on any failure (returns input unchanged).
    """
    if not html_content or 'cid:' not in html_content.lower():
        return html_content
    if not (email and token and cid_header and item_id):
        return html_content
    try:
        sess = requests.Session()
        headers = {
            'Authorization': f'Bearer {token}',
            'X-AnchorMailbox': str(email),
            'User-Agent': 'Outlook-Android/2.0',
            'Accept': 'application/json',
            'X-Routing-Hint': f'CID:{cid_header}',
            'ConsistencyLevel': 'eventual',
        }
        item_ref = requests.utils.requote_uri(str(item_id))
        inline_map = {}  # ContentId (no angle brackets) -> data URI
        for host in ('outlook.office.com', 'outlook.office365.com', 'outlook.live.com'):
            url = f'https://{host}/api/v2.0/me/messages/{item_ref}/attachments?$top=100'
            try:
                r = sess.get(url, headers=headers, timeout=15)
            except Exception:
                continue
            if r.status_code != 200:
                continue
            try:
                data = r.json()
            except Exception:
                continue
            for att in data.get('value', []) or []:
                if not att.get('IsInline'):
                    continue
                cid_id = (att.get('ContentId') or '').strip().strip('<>').strip('"')
                if not cid_id:
                    continue
                content_type = att.get('ContentType') or 'application/octet-stream'
                content_b64 = att.get('ContentBytes')
                if not content_b64:
                    # Some tenants only return metadata on the collection endpoint —
                    # fetch this single attachment by id to pick up its bytes.
                    att_id = att.get('Id')
                    if not att_id:
                        continue
                    try:
                        single_url = f'https://{host}/api/v2.0/me/messages/{item_ref}/attachments/{requests.utils.requote_uri(str(att_id))}'
                        r2 = sess.get(single_url, headers=headers, timeout=15)
                        if r2.status_code == 200:
                            j2 = r2.json()
                            content_b64 = j2.get('ContentBytes')
                            content_type = j2.get('ContentType') or content_type
                    except Exception:
                        pass
                if content_b64:
                    inline_map[cid_id.lower()] = f'data:{content_type};base64,{content_b64}'
            if inline_map:
                break  # got usable data from this host
        if not inline_map:
            return html_content

        def _repl(match):
            raw = match.group(2).strip().strip('"').strip("'").strip('<>')
            key = raw.lower()
            data_uri = inline_map.get(key)
            if not data_uri:
                # Some clients suffix "@example" on cids — try prefix-match too.
                for k, v in inline_map.items():
                    if key.startswith(k) or k.startswith(key):
                        data_uri = v
                        break
            if data_uri:
                return f'{match.group(1)}"{data_uri}"'
            return match.group(0)

        # Replace src="cid:..." and background="cid:..." variants (single + double quotes)
        pattern = re.compile(r'((?:src|background)\s*=\s*)(["\']?cid:[^"\'\s>]+["\']?)', re.IGNORECASE)
        return pattern.sub(_repl, html_content)
    except Exception:
        return html_content


def _bm23_make_body_browser(parent=None):
    """Return the best-available HTML body widget.

    If PyQt6.QtWebEngineWidgets is installed, return a QWebEngineView subclass
    with a QTextBrowser-compatible surface API (setHtml / setPlainText /
    setOpenExternalLinks) so existing call sites work unchanged. Javascript is
    disabled — email must never run script.

    Otherwise fall back to the regular QTextBrowser (limited CSS/img support).
    """
    if _BM23_WEBENGINE and QWebEngineView is not None:
        try:
            class _BM23WebBody(QWebEngineView):
                def __init__(self, p=None):
                    super().__init__(p)
                    s = self.settings()
                    s.setAttribute(QWebEngineSettings.WebAttribute.JavascriptEnabled, False)
                    s.setAttribute(QWebEngineSettings.WebAttribute.PluginsEnabled, False)
                    s.setAttribute(QWebEngineSettings.WebAttribute.AutoLoadImages, True)
                    s.setAttribute(QWebEngineSettings.WebAttribute.ErrorPageEnabled, False)
                    s.setAttribute(QWebEngineSettings.WebAttribute.ScrollAnimatorEnabled, True)
                    self._plain = ''
                    super().setHtml("<html><body style='background:#040806;margin:0;'></body></html>")

                def setHtml(self, html_content, base_url=None):
                    self._plain = re.sub(r'<[^>]+>', '',
                                          re.sub(r'<(script|style)[^>]*>.*?</\1>', '',
                                                 html_content or '', flags=re.DOTALL | re.IGNORECASE)).strip()
                    try:
                        from PyQt6.QtCore import QUrl as _QUrl
                        super().setHtml(html_content or '', base_url or _QUrl('https://outlook.live.com/'))
                    except Exception:
                        super().setHtml(html_content or '')

                def setPlainText(self, text):
                    self._plain = text or ''
                    esc = _html_stdlib.escape(self._plain)
                    super().setHtml(
                        f"<html><body style='background:#101020;color:#e8e8f5;font-family:Consolas,Menlo,monospace;"
                        f"font-size:12px;padding:14px;margin:0;'>"
                        f"<pre style='white-space:pre-wrap;word-wrap:break-word;'>{esc}</pre></body></html>"
                    )

                def toPlainText(self):
                    return self._plain

                def setOpenExternalLinks(self, _on):
                    # QWebEngineView opens external links via its own nav handler; no-op stub.
                    pass
            return _BM23WebBody(parent)
        except Exception:
            pass
    # Fallback path: QTextBrowser (imported later in the file via _sp_imp_9d17)
    _tb_mod = __import__('PyQt6.QtWidgets', None, None, ['QTextBrowser'])
    return _tb_mod.QTextBrowser(parent)


# ===== ARCHIVE MODULE (inlined) =====


def _sha256_bytes(data):
    return _hl.sha256(data).hexdigest()


def _hex_id():
    return uuid.uuid4().hex


def _safe_filename(name, max_len=80):
    safe = re.sub(r'[^\w\-. ]+', '_', name or 'unnamed')
    safe = re.sub(r'\s+', ' ', safe).strip()
    return (safe or 'unnamed')[:max_len]


class ArchiveResult:
    def __init__(self, msg_id, subject, archive_path, sha256, index_record):
        self.msg_id = msg_id
        self.subject = subject
        self.archive_path = archive_path
        self.sha256 = sha256
        self.index_record = index_record


def _build_mime_message(msg):
    subject = msg.get('subject', '') or ''
    from_addr = msg.get('from', '') or ''
    to_addrs = msg.get('to', []) or []
    date_str = msg.get('date', '') or ''
    message_id = msg.get('message_id') or msg.get('id') or ''

    msg_obj = email.message.EmailMessage()
    msg_obj['Subject'] = subject
    msg_obj['From'] = from_addr
    msg_obj['To'] = ', '.join(to_addrs) if isinstance(to_addrs, list) else to_addrs
    msg_obj['Date'] = date_str
    if message_id:
        msg_obj['Message-ID'] = message_id

    html_body = msg.get('html', '') or ''
    text_body = msg.get('text', '') or ''

    if html_body and text_body:
        msg_obj.set_content(text_body)
        msg_obj.add_alternative(html_body, subtype='html')
    elif html_body:
        msg_obj.set_content(html_body, subtype='html')
    elif text_body:
        msg_obj.set_content(text_body)
    else:
        msg_obj.set_content('')

    return msg_obj


def _save_eml(msg_obj, eml_path):
    raw_bytes = msg_obj.as_bytes(policy=SMTP)
    eml_path.write_bytes(raw_bytes)
    return raw_bytes


def _save_html(html_content, html_path):
    html_path.write_text(html_content, encoding='utf-8')


def _save_text(text_content, text_path):
    text_path.write_text(text_content or '', encoding='utf-8')


_BM23_INLINE_JUNK_MIN_IMAGE_BYTES = 15 * 1024   # < 15 KB image = probably icon/pixel/divider
_BM23_INLINE_NAME_JUNK_PATTERNS = re.compile(
    r'(signature|sig[-_]?\d+|icon|logo|divider|spacer|pixel|footer|header[-_]?bar|trans_?px|_1x1|smiley|emoji|button)',
    re.IGNORECASE,
)
_BM23_INLINE_MIME_SKIP = {'image/svg+xml', 'image/gif'}


def _bm23_is_junk_media(name, content_type, size, is_inline):
    """Classify an attachment as junk media (skip when sweeping for real photos/scans/docs).

    Rules:
      - non-inline never junk (user attached it deliberately)
      - SVG + GIF always junk (icons + emoji)
      - very small images (< 15KB) junk
      - filename hits known-icon/signature patterns → junk
      - non-image mime types (PDF, DOC, ZIP, video, etc) never junk
    """
    if not is_inline:
        return False
    ct = (content_type or '').lower()
    if ct in _BM23_INLINE_MIME_SKIP:
        return True
    if _BM23_INLINE_NAME_JUNK_PATTERNS.search(name or ''):
        return True
    if ct.startswith('image/'):
        try:
            if int(size or 0) < _BM23_INLINE_MIN_IMAGE_BYTES:
                return True
        except Exception:
            return True
        return False
    # non-image inline (weird — usually still worth keeping)
    return False


# Alias for the earlier constant name used in _bm23_is_junk_media.
_BM23_INLINE_MIN_IMAGE_BYTES = _BM23_INLINE_JUNK_MIN_IMAGE_BYTES


def _process_inline_attachments(msg, msg_dir, token, cid_header, msg_id):
    """Save real inline media (embedded scans, photos user pasted inline).
    Filters out icons/logos/SVG/signature junk via _bm23_is_junk_media.
    Returns list of saved-attachment dicts in the same shape as
    _process_attachments."""
    saved = []
    for att in msg.get('inline', []) or msg.get('inline_attachments', []) or []:
        att_name = att.get('name') or att.get('FileName') or 'inline_media'
        content_type = att.get('contentType') or att.get('ContentType') or 'application/octet-stream'
        size = att.get('size') or 0
        if _bm23_is_junk_media(att_name, content_type, size, is_inline=True):
            continue
        att_data = att.get('data') or att.get('payload') or b''
        if not att_data:
            continue
        safe_name = _safe_filename('inline_' + att_name)
        target = msg_dir / safe_name
        try:
            target.write_bytes(att_data)
        except Exception:
            continue
        saved.append({
            'name': att_name, 'path': str(target), 'size': len(att_data),
            'contentType': content_type, 'sha256': _sha256_bytes(att_data),
            'is_inline': True,
        })
    return saved


def _process_attachments(msg, msg_dir, token, cid_header, msg_id, mode='all'):
    saved = []
    attachments = msg.get('attachments', []) or []
    for att in attachments:
        att_name = att.get('name', att.get('FileName', 'unknown'))
        content_type = att.get('contentType', att.get('ContentType', 'application/octet-stream'))
        is_inline = bool(att.get('is_inline') or att.get('IsInline') or att.get('inline'))
        size = int(att.get('size') or 0)
        # Real attachments always kept; inline goes through the junk filter.
        if is_inline and _bm23_is_junk_media(att_name, content_type, size, is_inline=True):
            continue
        safe_name = _safe_filename(att_name)
        target = msg_dir / safe_name
        att_data = att.get('data') or att.get('payload') or b''
        if att_data:
            try:
                target.write_bytes(att_data)
            except Exception:
                continue
            saved.append({
                'name': att_name, 'path': str(target), 'size': len(att_data),
                'contentType': content_type, 'sha256': _sha256_bytes(att_data),
                'is_inline': is_inline,
                'ews_attachment_id': att.get('ews_attachment_id', ''),
            })
        else:
            # Metadata-only (EWS summary, no bytes fetched yet) — still record
            # so the attachment index shows it. Bytes fetch on-demand via
            # ews_attachment_id when user clicks OPEN in the index dialog.
            saved.append({
                'name': att_name, 'path': '', 'size': size,
                'contentType': content_type, 'sha256': '',
                'is_inline': is_inline,
                'ews_attachment_id': att.get('ews_attachment_id', ''),
                'meta_only': True,
            })
    return saved


def _bm23_normalize_ews_atts(ews_atts):
    """EWS GetItem response's Attachments[] → dicts _process_attachments understands.
    Bytes not included — call GetAttachment separately to download later."""
    out = []
    for a in ews_atts or []:
        try:
            aid = (a.get('AttachmentId') or {}).get('Id', '') or ''
            out.append({
                'name': a.get('Name', 'unnamed'),
                'FileName': a.get('Name', 'unnamed'),
                'contentType': a.get('ContentType', 'application/octet-stream'),
                'ContentType': a.get('ContentType', 'application/octet-stream'),
                'size': int(a.get('Size', 0) or 0),
                'is_inline': bool(a.get('IsInline', False)),
                'IsInline': bool(a.get('IsInline', False)),
                'content_id': a.get('ContentId', '') or '',
                'ews_attachment_id': aid,
                'ews_type': a.get('__type', ''),
            })
        except Exception: pass
    return out


