def _html_escape(s):
    # Coerce so dict/None/bytes don't crash the four .replace() chain (root cause
    # of the "'dict' object has no attribute 'replace'" restub error).
    if s is None:
        s = ''
    elif isinstance(s, (bytes, bytearray)):
        try:
            s = s.decode('utf-8', errors='replace')
        except Exception:
            s = ''
    elif isinstance(s, dict):
        for k in ('Content', 'Value', 'value', 'content', 'html', 'body', 'text'):
            if k in s and isinstance(s[k], str):
                s = s[k]; break
        else:
            try:
                s = __import__('json').dumps(s)
            except Exception:
                s = ''
    elif not isinstance(s, str):
        try:
            s = str(s)
        except Exception:
            s = ''
    return (s.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')
             .replace('"', '&quot;'))


