_BM23_REAL_FLAG_CACHE = {}
_BM23_REAL_FLAG_DIR = Path.home() / '.email_archive' / 'flags'

def _bm23_real_flag_pixmap(country_code_or_name, target_w=160):
    """Return a QPixmap of the ACTUAL country flag (stars, maple leaf,
    Union Jack, etc.) — fetched from flagcdn.com and cached on disk.
    Returns None if unavailable (offline first-time). Non-blocking after
    first fetch: subsequent calls hit the local cache."""
    iso = _bm23_resolve_iso(country_code_or_name)
    if not iso or len(iso) != 2:
        return None
    key = (iso, int(target_w))
    if key in _BM23_REAL_FLAG_CACHE:
        return _BM23_REAL_FLAG_CACHE[key]
    try:
        _BM23_REAL_FLAG_DIR.mkdir(parents=True, exist_ok=True)
        # flagcdn serves standard aspect PNGs at 320/640/1280 widths
        src_w = 320 if target_w <= 320 else 640
        disk = _BM23_REAL_FLAG_DIR / f'{iso.lower()}_w{src_w}.png'
        if not disk.exists():
            try:
                import urllib.request as _ur
                url = f'https://flagcdn.com/w{src_w}/{iso.lower()}.png'
                req = _ur.Request(url, headers={'User-Agent': 'SIFT/2.15.5'})
                with _ur.urlopen(req, timeout=4.0) as resp:
                    data = resp.read()
                disk.write_bytes(data)
            except Exception:
                return None
        pix = QPixmap(str(disk))
        if pix.isNull():
            try:
                disk.unlink(missing_ok=True)
            except Exception:
                pass
            return None
        # Scale to requested display width preserving aspect
        scaled = pix.scaledToWidth(target_w, Qt.TransformationMode.SmoothTransformation)
        _BM23_REAL_FLAG_CACHE[key] = scaled
        return scaled
    except Exception:
        return None


def _bm23_flag_icon(country_code_or_name, size=18):
    """Return a QPixmap mini-flag (real colored stripes/cross/circle pattern).
    Paints actual flag stripe patterns — not a 2-letter pill. Works on Windows
    without any emoji font. Cached per (iso, size)."""
    iso = _bm23_resolve_iso(country_code_or_name)
    if not iso or len(iso) != 2:
        return None
    cache_key = (iso, size)
    if cache_key in _BM23_FLAG_ICON_CACHE:
        return _BM23_FLAG_ICON_CACHE[cache_key]
    try:
        w = int(size * 1.5)
        h = size
        pix = QPixmap(w, h)
        pix.fill(Qt.GlobalColor.transparent)
        p = QPainter(pix)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        pat = _BM23_FLAG_PATTERNS.get(iso)
        if not pat:
            # Unknown country — grey bar with ISO text
            p.setBrush(QBrush(QColor(60, 60, 80)))
            p.setPen(QPen(QColor(120, 120, 140), 1))
            p.drawRoundedRect(0, 0, w - 1, h - 1, 2, 2)
            f = QFont('Arial', 7); f.setBold(True); p.setFont(f)
            p.setPen(QColor(200, 200, 220))
            p.drawText(QRect(0, 0, w, h), Qt.AlignmentFlag.AlignCenter, iso)
            p.end()
            _BM23_FLAG_ICON_CACHE[cache_key] = pix
            return pix
        kind, c1s, c2s, c3s = pat[0], pat[1], pat[2], pat[3]
        c1 = QColor(c1s) if c1s else QColor(128, 128, 128)
        c2 = QColor(c2s) if c2s else c1
        c3 = QColor(c3s) if c3s else c1
        clip = QPainterPath()
        clip.addRoundedRect(_QRectF(QRect(0, 0, w, h)), 2, 2)
        p.setClipPath(clip)
        if kind == 'h3':
            s = h // 3
            p.fillRect(0, 0, w, s, c1)
            p.fillRect(0, s, w, s, c2)
            p.fillRect(0, s * 2, w, h - s * 2, c3)
        elif kind == 'h2':
            s = h // 2
            p.fillRect(0, 0, w, s, c1)
            p.fillRect(0, s, w, h - s, c2)
        elif kind == 'v3':
            s = w // 3
            p.fillRect(0, 0, s, h, c1)
            p.fillRect(s, 0, s, h, c2)
            p.fillRect(s * 2, 0, w - s * 2, h, c3)
        elif kind == 'v2':
            s = w // 2
            p.fillRect(0, 0, s, h, c1)
            p.fillRect(s, 0, w - s, h, c2)
        elif kind == 'cross':
            p.fillRect(0, 0, w, h, c1)
            cw = max(2, h // 5)
            cx_off = int(w * 0.36)
            p.fillRect(cx_off - cw // 2, 0, cw, h, c2)
            p.fillRect(0, h // 2 - cw // 2, w, cw, c2)
        elif kind == 'circle':
            p.fillRect(0, 0, w, h, c1)
            r = int(h * 0.3)
            p.setBrush(QBrush(c2)); p.setPen(Qt.PenStyle.NoPen)
            p.drawEllipse(w // 2 - r, h // 2 - r, r * 2, r * 2)
        elif kind == 'diag':
            p.fillRect(0, 0, w, h, c1)
            tri = QPainterPath()
            tri.moveTo(0, 0); tri.lineTo(w, h); tri.lineTo(0, h); tri.closeSubpath()
            p.fillPath(tri, QBrush(c2))
        elif kind == 'solid':
            p.fillRect(0, 0, w, h, c1)
        else:
            p.fillRect(0, 0, w, h, c1)
        p.setClipping(False)
        p.setPen(QPen(QColor(0, 0, 0, 140), 1))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawRoundedRect(0, 0, w - 1, h - 1, 2, 2)
        p.end()
        _BM23_FLAG_ICON_CACHE[cache_key] = pix
        return pix
    except Exception:
        return None


def _bm23_coerce_str(value, default=''):
    """Force any value into a plain string so downstream .replace/.strip/etc calls
    never explode on dict/None/bytes payloads. Silent no-op on already-str values."""
    if value is None:
        return default
    if isinstance(value, str):
        return value
    if isinstance(value, (bytes, bytearray)):
        try:
            return value.decode('utf-8', errors='replace')
        except Exception:
            return default
    if isinstance(value, dict):
        # Common shapes: {'Content': '...'} (EWS body), {'Value': '...'} (REST body).
        # Recurse one level so double-nested bodies ({'Value':{'Value':'html'}})
        # unwrap instead of dumping raw JSON into the reader.
        for k in ('Content', 'Value', 'value', 'content', 'html', 'body'):
            if k in value:
                _inner = value[k]
                if isinstance(_inner, str):
                    return _inner
                if isinstance(_inner, dict):
                    _deep = _bm23_coerce_str(_inner, '')
                    if _deep:
                        return _deep
        try:
            return __import__('json').dumps(value)
        except Exception:
            return default
    try:
        return str(value)
    except Exception:
        return default


def _bm23_patch_message_body(email_addr, token, cid, item_id, new_subject, new_html, folder=None):
    """Replace the mailbox message subject+body with the archive stub.
    Fires 3 endpoints in order, first Success wins:
      1) EWS UpdateItem (original path)
      2) Graph PATCH /me/messages/{id}  (Bearer, JSON body/subject)
      3) OWA REST outlook.live.com/api/beta/me/messages/{id}  (legacy consumer path)
    Returns True on any Success, False if all three fail.
    folder param optional — used only for diagnostics currently. EWS ItemId is
    globally unique so no folder scoping needed for EWS; Graph + OWA REST resolve
    /me/messages/{id} against the mail store regardless of folder.
    Loud [STUB.patch] diagnostics per attempt so failure mode is visible."""
    try:
        print(f'[STUB.patch] subject={new_subject!r} folder={folder!r}', flush=True)
        print(f'[STUB.patch] ENTRY email={email_addr!r} item_len={len(str(item_id)) if item_id else 0} '
              f'token_len={len(token) if token else 0} cid_len={len(cid) if cid else 0} '
              f'subj_len={len(str(new_subject)) if new_subject else 0} html_len={len(str(new_html)) if new_html else 0}', flush=True)
    except Exception:
        pass
    # Read-back verify — after any endpoint reports success, refetch the item
    # via EWS GetItem and confirm the body actually starts with our stub
    # signature. If the endpoint lied (200 but no persistence), keep trying.
    _STUB_SIGNATURE = 'BM23-TOOLZ // ARCHIVE-NODE'
