# ===== ANIMATED TOGGLE SWITCH (BB8-inspired glow-slide toggle for PyQt) =====
class AnimatedToggle(QCheckBox):
    """Slide-and-glow animated toggle switch. Drop-in replacement for QCheckBox:
    same isChecked()/setChecked()/stateChanged API, just a nicer animated widget."""

    def __init__(self, parent=None, bar_color='#3a3a4e', bg_color='#1a1a26',
                 checked_color='#00e5a0', handle_color='#f4f4f4'):
        super().__init__(parent)
        self.setFixedSize(58, 30)
        self.setCursor(Qt.CursorShape.PointingHandCursor)

        self._bar_color = QColor(bar_color)
        self._bg_color = QColor(bg_color)
        self._checked_color = QColor(checked_color)
        self._handle_color = QColor(handle_color)

        self._handle_position = 0.0
        self._pulse_radius = 0.0

        self._anim = QPropertyAnimation(self, b'handle_position', self)
        self._anim.setDuration(220)
        self._anim.setEasingCurve(QEasingCurve.Type.OutCubic)

        self._pulse_anim = QPropertyAnimation(self, b'pulse_radius', self)
        self._pulse_anim.setDuration(360)
        self._pulse_anim.setEasingCurve(QEasingCurve.Type.OutQuad)

        self.stateChanged.connect(self._on_state_changed)

    def _on_state_changed(self, state):
        try:
            checked = self.isChecked()
        except Exception:
            try:
                checked = (int(state) == int(Qt.CheckState.Checked.value))
            except Exception:
                checked = bool(state) and state != 0
        self._anim.stop()
        self._anim.setStartValue(self._handle_position)
        self._anim.setEndValue(1.0 if checked else 0.0)
        self._anim.start()

        self._pulse_anim.stop()
        self._pulse_anim.setStartValue(0.0)
        self._pulse_anim.setEndValue(1.0 if checked else 0.0)
        self._pulse_anim.start()

    def get_handle_position(self):
        return self._handle_position

    def set_handle_position(self, pos):
        self._handle_position = pos
        self.update()

    handle_position = pyqtProperty(float, get_handle_position, set_handle_position)

    def get_pulse_radius(self):
        return self._pulse_radius

    def set_pulse_radius(self, r):
        self._pulse_radius = r
        self.update()

    pulse_radius = pyqtProperty(float, get_pulse_radius, set_pulse_radius)

    def hitButton(self, pos):
        return self.contentsRect().contains(pos)

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)

        rect = self.rect().adjusted(1, 1, -1, -1)
        bar_rect = QRectF(0, rect.height() * 0.28, rect.width(), rect.height() * 0.44)
        bar_rect.moveCenter(QPointF(rect.center().x(), rect.center().y()))

        t = self._handle_position
        bar_color = QColor(
            int(self._bg_color.red()   + (self._checked_color.red()   - self._bg_color.red())   * t),
            int(self._bg_color.green() + (self._checked_color.green() - self._bg_color.green()) * t),
            int(self._bg_color.blue()  + (self._checked_color.blue()  - self._bg_color.blue())  * t),
        )

        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(bar_color)
