def _1fe_599c16(size):
    """BM23 SIFT reactor icon — dark hex plate + cyan reactor ring + red
    plasma core + amber tick marks. Static, rendered per-size for crisp
    taskbar / titlebar output. Replaces the old green hotmail-checker
    logo across every window + system tray."""
    from PyQt6.QtGui import QRadialGradient, QLinearGradient
    px = QPixmap(size, size)
    px.fill(Qt.GlobalColor.transparent)
    p = QPainter(px)
    p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
    cx = size / 2; cy = size / 2
    # 1) Dark rounded base
    bg = QLinearGradient(0, 0, 0, size)
    bg.setColorAt(0.0, QColor(12, 18, 32))
    bg.setColorAt(1.0, QColor(2, 4, 12))
    p.setBrush(QBrush(bg)); p.setPen(Qt.PenStyle.NoPen)
    rr = int(size * 0.22)
    p.drawRoundedRect(0, 0, size, size, rr, rr)
    # 2) Hex outline plate
    import math as _m
    hex_r = size * 0.42
    pts = [QPointF(cx + hex_r * _m.cos(_m.pi / 6 + i * _m.pi / 3),
                   cy + hex_r * _m.sin(_m.pi / 6 + i * _m.pi / 3)) for i in range(6)]
    p.setPen(QPen(QColor(0, 240, 255, 140), max(1, int(size * 0.02))))
    p.setBrush(Qt.BrushStyle.NoBrush)
    for i in range(6):
        p.drawLine(pts[i], pts[(i + 1) % 6])
    # 3) Outer reactor ring — cyan
    p.setPen(QPen(QColor(0, 240, 255), max(1, int(size * 0.03))))
    ring_r = size * 0.33
    p.drawEllipse(QPointF(cx, cy), ring_r, ring_r)
    # 4) Tick marks every 60°
    p.setPen(QPen(QColor(255, 176, 0, 230), max(1, int(size * 0.02))))
    for i in range(6):
        ang = i * _m.pi / 3
        x1 = cx + ring_r * 0.85 * _m.cos(ang); y1 = cy + ring_r * 0.85 * _m.sin(ang)
        x2 = cx + ring_r * 1.10 * _m.cos(ang); y2 = cy + ring_r * 1.10 * _m.sin(ang)
        p.drawLine(QPointF(x1, y1), QPointF(x2, y2))
    # 5) Blue plasma core (was red — user is bluemeanie23, not redmeanie23)
    core_r = size * 0.20
    core = QRadialGradient(cx, cy, core_r * 1.6)
    core.setColorAt(0.0, QColor(255, 255, 255, 255))
    core.setColorAt(0.25, QColor(120, 180, 255, 240))
    core.setColorAt(0.6, QColor(30, 100, 255, 200))
    core.setColorAt(1.0, QColor(0, 20, 90, 0))
    p.setBrush(QBrush(core)); p.setPen(Qt.PenStyle.NoPen)
    p.drawEllipse(QPointF(cx, cy), core_r, core_r)
    # 6) Corner brackets (mini) for reactor identity
    br_len = int(size * 0.14); br_m = int(size * 0.10)
    p.setPen(QPen(QColor(0, 240, 255, 200), max(1, int(size * 0.02))))
    for bx, by, dx, dy in ((br_m, br_m, 1, 1), (size - br_m, br_m, -1, 1),
                           (br_m, size - br_m, 1, -1), (size - br_m, size - br_m, -1, -1)):
        p.drawLine(bx, by, bx + dx * br_len, by)
        p.drawLine(bx, by, bx, by + dy * br_len)
    p.end()
    return px

