def _bm23_get_country(country_code):
    """Look up country DB entry — featured 10 get bespoke palette, everyone else
    gets the generic burst template with the correct country name substituted in."""
    if not country_code:
        return None
    cc = str(country_code).upper().strip()
    if cc in _BM23_COUNTRY_FEATURED and cc in _BM23_COUNTRY_DB:
        return _BM23_COUNTRY_DB[cc]
    # Non-featured: build generic entry on the fly with the real country name.
    name = _BM23_ISO_TO_NAME.get(cc) or cc
    entry = dict(_BM23_COUNTRY_GENERIC)
    entry['name'] = name
    return entry


# ---------------------------------------------------------------------------
# Dopamine helpers — screen shake + full-screen flash on popup summon.
# Bluemeanie asked for "in your face" — this is that. Cheap tricks that stack.
# ---------------------------------------------------------------------------

_BM23_SHAKE_LOCK = False           # true while a shake is running so overlapping hits don't stack
_BM23_LAST_FX_MS = 0               # monotonic ms of the last effect burst — hard rate-limit gate
_BM23_FX_COOLDOWN_MS = 550         # min gap between full FX runs (screen shake + flash + self-shake)


def _bm23_can_run_fx():
    """Rate-limit gate. Popup summons burst FX; if hits pile up we skip the
    extras (still show the popup) so we don't melt the CPU / freeze the UI."""
    global _BM23_LAST_FX_MS
    try:
        import time as _t
        now = int(_t.monotonic() * 1000)
        if now - _BM23_LAST_FX_MS < _BM23_FX_COOLDOWN_MS:
            return False
        _BM23_LAST_FX_MS = now
        return True
    except Exception:
        return True


def _bm23_trigger_screen_shake(duration_ms=220, magnitude=8):
    """Wiggle the MAIN app window for ~220ms. Only the active window (not every
    top-level) so we don't reflow the entire desktop on every popup."""
    global _BM23_SHAKE_LOCK
    if _BM23_SHAKE_LOCK:
        return
    try:
        app = _sp_imp_9d17.QApplication.instance()
        if app is None:
            return
        target = app.activeWindow()
        if target is None:
            # Fall back to the first visible non-tool non-popup window
            for w in app.topLevelWidgets():
                try:
                    flags = w.windowFlags()
                    if bool(int(flags) & int(Qt.WindowType.Tool)):
                        continue
                    if not w.isVisible():
                        continue
                    if w.__class__.__name__ in ('_BM23BurstPopup', '_BM23EpicPopup', '_BM23FlashOverlay'):
                        continue
                    target = w
                    break
                except Exception:
                    continue
        if target is None:
            return
        try:
            if target.__class__.__name__ in ('_BM23BurstPopup', '_BM23EpicPopup', '_BM23FlashOverlay'):
                return
        except Exception:
            return
        origin = QPoint(target.pos())
        _BM23_SHAKE_LOCK = True
        state = {'step': 0}
        total_steps = max(4, int(duration_ms / 32))  # ~30fps instead of 40 — 32ms steps

        def _tick():
            global _BM23_SHAKE_LOCK
            if state['step'] >= total_steps:
                try:
                    target.move(origin)
                except RuntimeError:
                    pass
                _BM23_SHAKE_LOCK = False
                return
            decay = 1.0 - (state['step'] / total_steps)
            mag = max(1, int(magnitude * decay))
            try:
                dx = _bm23_random.randint(-mag, mag)
                dy = _bm23_random.randint(-mag, mag)
                target.move(origin.x() + dx, origin.y() + dy)
            except RuntimeError:
                _BM23_SHAKE_LOCK = False
                return
            state['step'] += 1
            _QTimer.singleShot(32, _tick)

        _tick()
    except Exception:
        _BM23_SHAKE_LOCK = False


class _BM23FlashOverlay(QWidget):
    """Full-screen frameless white overlay that fades from ~30% opacity to 0.
    Purely visual dopamine — no interaction, click-through disabled."""
    def __init__(self, screen_geom, parent=None):
        super().__init__(parent)
        self.setWindowFlags(
            Qt.WindowType.FramelessWindowHint
            | Qt.WindowType.WindowStaysOnTopHint
            | Qt.WindowType.Tool
            | Qt.WindowType.WindowTransparentForInput
        )
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self.setAttribute(Qt.WidgetAttribute.WA_ShowWithoutActivating, True)
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        self.setGeometry(screen_geom)
        self._anim = None

    def paintEvent(self, _e):
        try:
            p = QPainter(self)
            p.fillRect(self.rect(), QColor(255, 255, 255, 90))
            p.end()
        except Exception:
            pass


def _bm23_flash_screen(duration_ms=180):
    """Quick white flash across the full primary screen — 180ms fade-out."""
    try:
        screen = QGuiApplication.primaryScreen()
        if screen is None:
            return
        overlay = _BM23FlashOverlay(screen.availableGeometry())
        overlay.setWindowOpacity(0.9)
        overlay.show()
        anim = QPropertyAnimation(overlay, b'windowOpacity', overlay)
        anim.setDuration(duration_ms)
        anim.setStartValue(0.9)
        anim.setEndValue(0.0)
        anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        anim.finished.connect(overlay.close)
        anim.start(QPropertyAnimation.DeletionPolicy.DeleteWhenStopped)
    except Exception:
        pass


class _BM23SplashEnter(QDialog):
    """Fullscreen reactor boot splash — mycelium colony growing outward from
    the reactor core, wordmark reveals as hyphae reach it, boot-log ticker
    at bottom. Living, not static. Click/Enter/Space to boot."""
    enter_clicked = pyqtSignal()

    _BOOT_LOG = [
        'REACTOR CORE ONLINE',
        'HYPHAL NETWORK SEEDED',
        'NUTRIENT MAP LOADED',
        'IMAP HANDSHAKE STAGED',
        'EWS FALLBACK ARMED',
        'VENDOR LIST · 622 SIGNATURES',
        'KEYWORD LIST · 240 TOKENS',
        'STUB TEMPLATE COMPILED',
        'JOB REGISTRY MOUNTED',
        'REACTOR STANDBY · press ENTER',
    ]

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowFlags(Qt.WindowType.FramelessWindowHint | Qt.WindowType.Dialog)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self.setModal(True)
        try:
            screen = QGuiApplication.primaryScreen()
            if screen is not None:
                g = screen.geometry()
                self.setFixedSize(g.width(), g.height())
                self.move(g.left(), g.top())
        except Exception:
            self.setFixedSize(1920, 1080)
        self._hover = False
        self._frame = 0
        import random as _rnd
        self._rng = _rnd.Random(0xB0075)
        w, h = self.width(), self.height()
        import math as _m
        # (a) Ambient wrapping-dot sprites
        self._sprites = []
        for _ in range(80):
            self._sprites.append({
                'x': self._rng.random() * w,
                'y': self._rng.random() * h,
                'vx': (self._rng.random() - 0.5) * 1.2,
                'vy': (self._rng.random() - 0.5) * 1.2,
            })
        # (b) Boids-style orbit triangles around reactor core
        self._orbiters = []
        for i in range(18):
            self._orbiters.append({
                'orbit': min(w, h) * (0.10 + self._rng.random() * 0.28),
                'ang': self._rng.random() * 6.283,
                'spd': 0.008 + self._rng.random() * 0.024,
                'sign': 1 if self._rng.random() < 0.5 else -1,
                'sz': 3 + self._rng.random() * 3,
            })
        # (c) Mycelium tips flaring out of core, chasing radial nutrients
        self._tips = []
        for i in range(10):
            ang = i * (2 * _m.pi / 10) + self._rng.random() * 0.3
            self._tips.append({'x': w / 2, 'y': h / 2, 'a': ang, 'age': 0, 'w': 2.2})
        self._segments = []
        self._nutr = []
        for _ in range(40):
            r = min(w, h) * (0.20 + self._rng.random() * 0.30)
            a = self._rng.random() * 6.283
            self._nutr.append({'x': w / 2 + r * _m.cos(a), 'y': h / 2 + r * _m.sin(a)})
        # (d) Radial energy bursts pinging out of core every 1.2s
        self._pings = []
        self._last_ping_frame = -1
        # (e) Core rotation angle
        self._core_spin = 0.0
        # Boot log tick counter
        self._boot_progress = 0
        self._boot_index = 0
        # Wordmark reveal — 0..1 progress based on frames elapsed
        self._reveal = 0.0
        # Corner L brackets pre-baked
        self._t = _QTimer(self)
        self._t.timeout.connect(self._tick)
        self._t.start(33)

    def _tick(self):
        import math as _m
        self._frame += 1
        w = self.width(); h = self.height()
        # (a) Ambient wrapping sprites
        for s in self._sprites:
            s['x'] = (s['x'] + s['vx']) % w
            s['y'] = (s['y'] + s['vy']) % h
        # (b) Orbiters advance
        for o in self._orbiters:
            o['ang'] += o['spd'] * o['sign']
        # (c) Mycelium grow (same algorithm as mailbox panel)
        alive = []
        for tp in self._tips:
            bt = None; bd = 1e9
            for n in self._nutr:
                d = (n['x'] - tp['x']) ** 2 + (n['y'] - tp['y']) ** 2
                if d < bd:
                    bd = d; bt = n
            if bt is not None:
                ta = _m.atan2(bt['y'] - tp['y'], bt['x'] - tp['x'])
                da = _m.atan2(_m.sin(ta - tp['a']), _m.cos(ta - tp['a']))
                tp['a'] += da * 0.06 + (self._rng.random() - 0.5) * 0.42
            nx = tp['x'] + _m.cos(tp['a']) * 2.2
            ny = tp['y'] + _m.sin(tp['a']) * 2.2
            self._segments.append({'x1': tp['x'], 'y1': tp['y'], 'x2': nx, 'y2': ny,
                                    'w': max(0.4, tp['w']), 'life': 1.0})
            tp['x'] = nx; tp['y'] = ny; tp['age'] += 1
            tp['w'] *= 0.9992
            if bt is not None and bd < 144:
                try: self._nutr.remove(bt)
                except ValueError: pass
                # Respawn nutrient elsewhere so growth continues
                r = min(w, h) * (0.20 + self._rng.random() * 0.30)
                ang2 = self._rng.random() * 6.283
                self._nutr.append({'x': w / 2 + r * _m.cos(ang2), 'y': h / 2 + r * _m.sin(ang2)})
            if self._rng.random() < 0.028 and (len(self._tips) + len(alive)) < 120:
                alive.append({'x': tp['x'], 'y': tp['y'],
                              'a': tp['a'] + (0.5 + self._rng.random() * 0.6) * (1 if self._rng.random() < 0.5 else -1),
                              'age': 0, 'w': tp['w'] * 0.8})
            if (tp['x'] < 0 or tp['x'] > w or tp['y'] < 0 or tp['y'] > h
                    or tp['age'] > 700 or tp['w'] < 0.35):
                continue
            alive.append(tp)
        if len(alive) < 6:
            for i in range(6):
                alive.append({'x': w / 2, 'y': h / 2, 'a': self._rng.random() * 6.283, 'age': 0, 'w': 2.0})
        self._tips = alive
        for s in self._segments: s['life'] -= 0.0022
        self._segments = [s for s in self._segments if s['life'] > 0.05]
        if len(self._segments) > 900: self._segments = self._segments[-900:]
        # (d) Emit ping every ~36 frames (~1.2s)
        if self._frame - self._last_ping_frame > 36:
            self._pings.append({'r': 8, 'life': 1.0})
            self._last_ping_frame = self._frame
        for pg in self._pings:
            pg['r'] += 6
            pg['life'] -= 0.012
        self._pings = [pg for pg in self._pings if pg['life'] > 0.05]
        # (e) Reactor core spin
        self._core_spin += 0.05
        # Boot log tick
        if self._frame % 24 == 0 and self._boot_index < len(self._BOOT_LOG):
            self._boot_index += 1
        self._reveal = 1.0
        self.update()
        return
        # ---- unreachable: legacy mycelium loop kept for reference ----
        alive = []
        for tp in self._tips:
            # Chemotaxis toward nearest nutrient
            bt = None; bd = 1e9
            for n in self._nutr:
                d = (n['x'] - tp['x']) ** 2 + (n['y'] - tp['y']) ** 2
                if d < bd:
                    bd = d; bt = n
            if bt is not None:
                ta = _m.atan2(bt['y'] - tp['y'], bt['x'] - tp['x'])
                da = _m.atan2(_m.sin(ta - tp['a']), _m.cos(ta - tp['a']))
                tp['a'] += da * 0.06 + (self._rng.random() - 0.5) * 0.42
            else:
                tp['a'] += (self._rng.random() - 0.5) * 0.4
            nx = tp['x'] + _m.cos(tp['a']) * 2.4
            ny = tp['y'] + _m.sin(tp['a']) * 2.4
            self._segments.append({
                'x1': tp['x'], 'y1': tp['y'], 'x2': nx, 'y2': ny,
                'w': max(0.5, tp['w']), 'life': 1.0,
            })
            tp['x'] = nx; tp['y'] = ny; tp['age'] += 1
            tp['w'] *= 0.9992
            # Consume nutrient
            if bt is not None and bd < 144:
                try:
                    self._nutr.remove(bt)
                except ValueError:
                    pass
            # Branch
            if self._rng.random() < 0.032 and (len(self._tips) + len(alive)) < 180:
                alive.append({
                    'x': tp['x'], 'y': tp['y'],
                    'a': tp['a'] + (0.5 + self._rng.random() * 0.6) * (1 if self._rng.random() < 0.5 else -1),
                    'age': 0, 'w': tp['w'] * 0.8,
                })
            # Drop conditions
            if (tp['x'] < 0 or tp['x'] > w or tp['y'] < 0 or tp['y'] > h
                    or tp['age'] > 900 or tp['w'] < 0.35):
                continue
            alive.append(tp)
        # Refill if sparse
        if len(alive) < 6:
            cx, cy = w / 2.0, h / 2.0
            for i in range(6):
                ang = self._rng.random() * 6.283
                alive.append({'x': cx, 'y': cy, 'a': ang, 'age': 0, 'w': 2.0})
        self._tips = alive
        # Age segments
        for s in self._segments:
            s['life'] -= 0.0018
        self._segments = [s for s in self._segments if s['life'] > 0.05]
        if len(self._segments) > 1400:
            self._segments = self._segments[-1400:]
        # Boot log tick every ~24 frames (~0.8s)
        if self._frame % 24 == 0 and self._boot_index < len(self._BOOT_LOG):
            self._boot_index += 1
        # Wordmark reveal starts frame 15, done by frame 90
        self._reveal = max(0.0, min(1.0, (self._frame - 15) / 75.0))
        self.update()

    def paintEvent(self, _e):
        try:
            import math as _m
            from PyQt6.QtGui import QRadialGradient, QLinearGradient
            p = QPainter(self)
            p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            p.setRenderHint(QPainter.RenderHint.TextAntialiasing, True)
            w, h = self.width(), self.height()
            cx = w // 2; cy = h // 2
            # === App 2-tone reactor palette + graffiti flair ===
            BLACK = QColor(6, 6, 14)
            CYAN = QColor(0, 240, 255)
            RED = QColor(255, 32, 64)
            AMBER = QColor(255, 176, 0)
            GREEN = QColor(0, 255, 136)
            MAGENTA = QColor(255, 70, 200)
            DIM_CYAN = QColor(0, 120, 130)
            WHITE = QColor(240, 250, 255)
            # Gradient bg — deep navy top, warm plum bottom (2-tone base)
            bg_grad = QLinearGradient(0, 0, 0, h)
            bg_grad.setColorAt(0.0, QColor(4, 8, 22))
            bg_grad.setColorAt(0.5, QColor(8, 4, 18))
            bg_grad.setColorAt(1.0, QColor(20, 4, 12))
            p.fillRect(0, 0, w, h, QBrush(bg_grad))
            # Industrial isometric wireframe grid — thin cyan/red hairlines
            grid_step = int(h * 0.045)
            p.setPen(QPen(QColor(0, 240, 255, 26), 1))
            # 30° iso lines /
            for i in range(-h, w + h, grid_step):
                p.drawLine(i, 0, i + int(h * 0.577), h)
            p.setPen(QPen(QColor(255, 32, 64, 20), 1))
            # 30° iso lines \
            for i in range(0, w + h, grid_step):
                p.drawLine(i, 0, i - int(h * 0.577), h)
            # Horizontal industrial rails
            p.setPen(QPen(QColor(255, 176, 0, 18), 1))
            for y in range(0, h, grid_step):
                p.drawLine(0, y, w, y)
            # Radial reactor grid (kept but 2-tone: half cyan, half red)
            p.setBrush(Qt.BrushStyle.NoBrush)
            for r in range(int(h * 0.08), int(max(w, h) * 1.1), int(h * 0.10)):
                col = QColor(0, 240, 255, 32) if (r // int(h * 0.10)) % 2 == 0 else QColor(255, 32, 64, 32)
                p.setPen(QPen(col, 1))
                p.drawEllipse(QPointF(cx, cy), r, r)
            for i, ang_deg in enumerate(range(0, 360, 15)):
                col = QColor(0, 240, 255, 28) if i % 2 == 0 else QColor(255, 32, 64, 28)
                p.setPen(QPen(col, 1))
                rad = _m.radians(ang_deg)
                ex = cx + int(max(w, h) * 1.3 * _m.cos(rad))
                ey = cy + int(max(w, h) * 1.3 * _m.sin(rad))
                p.drawLine(cx, cy, ex, ey)
            # Corner rivet plates — industrial trim
            plate_sz = int(h * 0.08)
            for cx_p, cy_p in ((plate_sz, plate_sz),
                                (w - plate_sz, plate_sz),
                                (plate_sz, h - plate_sz),
                                (w - plate_sz, h - plate_sz)):
                p.setPen(QPen(QColor(0, 240, 255, 120), 1.5))
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawRect(cx_p - plate_sz // 2, cy_p - plate_sz // 2, plate_sz, plate_sz)
                # 4 rivets
                for rx, ry in ((-plate_sz // 3, -plate_sz // 3),
                                (plate_sz // 3, -plate_sz // 3),
                                (-plate_sz // 3, plate_sz // 3),
                                (plate_sz // 3, plate_sz // 3)):
                    p.setBrush(QBrush(QColor(255, 176, 0, 200)))
                    p.setPen(Qt.PenStyle.NoPen)
                    p.drawEllipse(QPointF(cx_p + rx, cy_p + ry), 3, 3)
            # Ambient wrapping sprite dots
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QBrush(CYAN))
            for s in self._sprites:
                p.drawEllipse(QPointF(s['x'], s['y']), 2, 2)
            # ----- Mycelium segments (brown base + cyan glow) -----
            base_col = QColor(78, 40, 15)
            for seg in self._segments:
                a = min(1.0, seg['life'])
                base_col.setAlpha(int(120 * a))
                p.setPen(QPen(base_col, max(0.5, seg['w'])))
                p.drawLine(QPointF(seg['x1'], seg['y1']), QPointF(seg['x2'], seg['y2']))
                if a > 0.55:
                    glow_a = int(210 * (a - 0.55) / 0.45)
                    p.setPen(QPen(QColor(0, 255, 204, glow_a), max(0.5, seg['w'] * 0.7)))
                    p.drawLine(QPointF(seg['x1'], seg['y1']), QPointF(seg['x2'], seg['y2']))
            # Mycelium tip glow dots
            for tp in self._tips:
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QBrush(QColor(0, 255, 204, 100)))
                p.drawEllipse(QPointF(tp['x'], tp['y']), 4, 4)
                p.setBrush(QBrush(WHITE))
                p.drawEllipse(QPointF(tp['x'], tp['y']), 1.4, 1.4)
            # Nutrient shimmer
            for n in self._nutr:
                a_n = int(70 + 60 * _m.sin(self._frame * 0.1 + n['x'] * 0.01))
                p.setBrush(QBrush(QColor(0, 255, 204, a_n)))
                p.drawEllipse(QPointF(n['x'], n['y']), 3, 3)
            # ----- Radial pings pulsing out of core -----
            for pg in self._pings:
                a_p = int(180 * pg['life'])
                p.setPen(QPen(QColor(0, 255, 204, a_p), 1.4))
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawEllipse(QPointF(cx, cy + int(h * 0.015)), pg['r'], pg['r'])
            # ----- Orbiter triangles around core -----
            from PyQt6.QtGui import QPolygonF
            for o in self._orbiters:
                ox = cx + o['orbit'] * _m.cos(o['ang'])
                oy = cy + int(h * 0.015) + o['orbit'] * _m.sin(o['ang']) * 0.55
                head = o['ang'] + (_m.pi / 2 if o['sign'] > 0 else -_m.pi / 2)
                p.save()
                p.translate(ox, oy)
                p.rotate(_m.degrees(head))
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QBrush(CYAN))
                p.drawPolygon(QPolygonF([
                    QPointF(o['sz'], 0),
                    QPointF(-o['sz'] * 0.7, o['sz'] * 0.55),
                    QPointF(-o['sz'] * 0.7, -o['sz'] * 0.55),
                ]))
                p.restore()
            # 1) GRAFFITI-STYLE TITLE — tilted chunky black-book tag with
            #    multi-color drop shadow, magenta+cyan RGB split, amber halo.
            f_title = QFont('Arial Black', int(h * 0.11))
            f_title.setBold(True)
            f_title.setItalic(True)  # graffiti lean
            f_title.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, int(h * 0.004))
            p.setFont(f_title)
            title_rect = QRect(0, int(h * 0.11), w, int(h * 0.15))
            # Slight rotation for tag-lean
            p.save()
            p.translate(cx, int(h * 0.185))
            p.rotate(-3)
            p.translate(-cx, -int(h * 0.185))
            # Amber halo (biggest offset)
            p.setPen(AMBER)
            p.drawText(title_rect.translated(8, 8), Qt.AlignmentFlag.AlignCenter, 'BM23-TOOLZ-SIFT')
            # Magenta shadow
            p.setPen(MAGENTA)
            p.drawText(title_rect.translated(5, 5), Qt.AlignmentFlag.AlignCenter, 'BM23-TOOLZ-SIFT')
            # Red shadow
            p.setPen(RED)
            p.drawText(title_rect.translated(3, 3), Qt.AlignmentFlag.AlignCenter, 'BM23-TOOLZ-SIFT')
            # Cyan shadow (near)
            p.setPen(CYAN)
            p.drawText(title_rect.translated(-2, -2), Qt.AlignmentFlag.AlignCenter, 'BM23-TOOLZ-SIFT')
            # White core
            p.setPen(WHITE)
            p.drawText(title_rect, Qt.AlignmentFlag.AlignCenter, 'BM23-TOOLZ-SIFT')
            # Under-tag scribble line — cyan → red → amber
            underline_y = int(h * 0.26)
            seg_w = int(w * 0.11)
            for i, col in enumerate((CYAN, RED, AMBER, GREEN, MAGENTA)):
                p.setPen(QPen(col, 3))
                sx = cx - int(w * 0.19) + i * (seg_w // 3)
                p.drawLine(sx, underline_y + (i % 2) * 2, sx + seg_w // 3, underline_y)
            p.restore()
            # 2) SUB-HEADER — graffiti stencil style, layered colors
            f_sub = QFont('Impact', int(h * 0.022))
            f_sub.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, int(h * 0.008))
            p.setFont(f_sub)
            # Red offset shadow
            p.setPen(QColor(255, 32, 64, 180))
            p.drawText(QRect(3, int(h * 0.32) + 2, w, int(h * 0.04)),
                       Qt.AlignmentFlag.AlignCenter,
                       'MAILBOX  //  RECLAMATION  //  REACTOR')
            p.setPen(CYAN)
            p.drawText(QRect(0, int(h * 0.32), w, int(h * 0.04)),
                       Qt.AlignmentFlag.AlignCenter,
                       'MAILBOX  //  RECLAMATION  //  REACTOR')
            # Version — spray-stencil small
            f_ver = QFont('Impact', int(h * 0.014))
            f_ver.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, int(h * 0.006))
            p.setFont(f_ver)
            p.setPen(AMBER)
            p.drawText(QRect(0, int(h * 0.37), w, int(h * 0.03)),
                       Qt.AlignmentFlag.AlignCenter,
                       f'v2.15.5  ·  {_BM23_BUILD_STAMP}  ·  BY BLUEMEANIE23')
            # 3) CENTRAL BOOLEAN REACTOR NODE — heavily animated:
            #    - Outer ring pulses
            #    - Inner ring counter-rotates
            #    - Crosshair spins
            #    - Core throbs
            #    - Concentric halos ping
            node_cy = cy + int(h * 0.015)
            node_r = int(h * 0.045)
            spin = self._core_spin
            pulse = 0.5 + 0.5 * _m.sin(self._frame * 0.08)
            # Outer soft halo
            for extra, aa in ((14, 24), (8, 55), (4, 90)):
                p.setPen(QPen(QColor(0, 255, 204, aa), 1))
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawEllipse(QPointF(cx, node_cy), node_r + extra, node_r + extra)
            # Rotating outer arc segments — 3 arcs at 120°
            outer_r = node_r + 8
            p.setPen(QPen(CYAN, 2))
            for k in range(3):
                start_ang = int(_m.degrees(spin + k * 2 * _m.pi / 3)) * 16
                p.drawArc(int(cx - outer_r), int(node_cy - outer_r),
                          int(outer_r * 2), int(outer_r * 2), start_ang, 60 * 16)
            # Main ring pulsing thickness
            p.setPen(QPen(CYAN, 2 + int(2 * pulse)))
            p.drawEllipse(QPointF(cx, node_cy), node_r, node_r)
            # Counter-rotating inner ring
            in_r = node_r * 0.65
            p.setPen(QPen(QColor(0, 200, 170, 200), 1.4))
            for k in range(4):
                start_ang = int(_m.degrees(-spin * 1.6 + k * _m.pi / 2)) * 16
                p.drawArc(int(cx - in_r), int(node_cy - in_r),
                          int(in_r * 2), int(in_r * 2), start_ang, 45 * 16)
            # Spinning crosshair (main + secondary at 45°)
            crosshair = int(node_r * 0.60)
            p.setPen(QPen(CYAN, 1.5))
            for offset_ang in (0.0, _m.pi / 4):
                a1 = spin + offset_ang
                x1 = cx + crosshair * _m.cos(a1); y1 = node_cy + crosshair * _m.sin(a1)
                x2 = cx - crosshair * _m.cos(a1); y2 = node_cy - crosshair * _m.sin(a1)
                p.drawLine(int(x1), int(y1), int(x2), int(y2))
                # Perpendicular
                a2 = a1 + _m.pi / 2
                x3 = cx + crosshair * _m.cos(a2); y3 = node_cy + crosshair * _m.sin(a2)
                x4 = cx - crosshair * _m.cos(a2); y4 = node_cy - crosshair * _m.sin(a2)
                p.drawLine(int(x3), int(y3), int(x4), int(y4))
            # Core throb — radial gradient, white-hot
            core_r = node_r * (0.20 + 0.10 * pulse)
            from PyQt6.QtGui import QRadialGradient as _QRG
            cg = _QRG(cx, node_cy, core_r * 3)
            cg.setColorAt(0.0, QColor(255, 255, 255, 255))
            cg.setColorAt(0.35, QColor(0, 255, 204, 220))
            cg.setColorAt(1.0, QColor(0, 0, 0, 0))
            p.fillRect(int(cx - core_r * 3), int(node_cy - core_r * 3),
                       int(core_r * 6), int(core_r * 6), QBrush(cg))
            # 4 orbiting satellite dots on the ring
            for k in range(4):
                sa = -spin * 2.4 + k * _m.pi / 2
                sx = cx + node_r * _m.cos(sa)
                sy = node_cy + node_r * _m.sin(sa)
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QBrush(QColor(255, 255, 255, 240)))
                p.drawEllipse(QPointF(sx, sy), 3, 3)
                p.setBrush(QBrush(QColor(0, 255, 204, 90)))
                p.drawEllipse(QPointF(sx, sy), 6, 6)
            # 4) BOOT STATUS LIST — graffiti tags, each color-cycled
            f_status = QFont('Impact', int(h * 0.019))
            f_status.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, int(h * 0.003))
            p.setFont(f_status)
            recent = self._BOOT_LOG[max(0, self._boot_index - 3):self._boot_index]
            list_top = int(h * 0.71)
            row_h = int(h * 0.034)
            row_cols = [CYAN, MAGENTA, AMBER, GREEN]
            max_w = 0
            fm = p.fontMetrics()
            entries = []
            for i, entry in enumerate(recent):
                is_last = (i == len(recent) - 1) and (self._boot_index < len(self._BOOT_LOG))
                caret = '▶  ' if is_last else '✓  '
                text = f'{caret}{entry}'
                entries.append((text, is_last))
                tw = fm.horizontalAdvance(text)
                if tw > max_w: max_w = tw
            block_x = int(cx - max_w / 2)
            for i, (text, is_last) in enumerate(entries):
                col = WHITE if is_last else row_cols[(self._boot_index - len(recent) + i) % len(row_cols)]
                # 1-px red drop shadow for tag feel
                p.setPen(QColor(255, 32, 64, 180))
                p.drawText(block_x + 2, list_top + i * row_h + 2, text)
                p.setPen(col)
                p.drawText(block_x, list_top + i * row_h, text)
            # 5) BOOT PROGRESS BAR — 2-tone gradient with amber endcap
            bar_w = int(w * 0.34); bar_h = int(max(6, h * 0.010))
            bar_x = int(cx - bar_w / 2); bar_y = int(h * 0.86)
            # Track — dark red-cyan wash
            track_g = QLinearGradient(bar_x, 0, bar_x + bar_w, 0)
            track_g.setColorAt(0.0, QColor(0, 60, 80))
            track_g.setColorAt(1.0, QColor(80, 10, 30))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QBrush(track_g))
            p.drawRect(bar_x, bar_y, bar_w, bar_h)
            # Fill — cyan → red → amber rainbow
            prog_pct = self._boot_index / len(self._BOOT_LOG)
            fill_w = int(bar_w * prog_pct)
            fill_g = QLinearGradient(bar_x, 0, bar_x + fill_w, 0)
            fill_g.setColorAt(0.0, CYAN)
            fill_g.setColorAt(0.5, MAGENTA)
            fill_g.setColorAt(1.0, AMBER)
            p.setBrush(QBrush(fill_g))
            p.drawRect(bar_x, bar_y, fill_w, bar_h)
            # Endcap
            if fill_w > 0:
                p.setBrush(QBrush(WHITE))
                p.drawEllipse(QPointF(bar_x + fill_w, bar_y + bar_h / 2), 5, 5)
            # Percent — graffiti label
            f_pct = QFont('Impact', int(h * 0.018))
            f_pct.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, int(h * 0.005))
            p.setFont(f_pct)
            p.setPen(QColor(255, 32, 64, 180))
            p.drawText(QRect(2, bar_y + bar_h + int(h * 0.012) + 1, w, int(h * 0.04)),
                       Qt.AlignmentFlag.AlignCenter,
                       f'BOOT SEQUENCE   //   {int(prog_pct * 100)}%')
            p.setPen(CYAN)
            p.drawText(QRect(0, bar_y + bar_h + int(h * 0.012), w, int(h * 0.04)),
                       Qt.AlignmentFlag.AlignCenter,
                       f'BOOT SEQUENCE   //   {int(prog_pct * 100)}%')
            # 6) ENTER hint — only when boot done
            btn_ready = self._boot_index >= len(self._BOOT_LOG)
            if btn_ready:
                f_enter = QFont('Impact', int(h * 0.036))
                f_enter.setItalic(True)
                f_enter.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, int(h * 0.012))
                p.setFont(f_enter)
                text = 'PRESS  ENTER  TO  BOOT'
                r = QRect(0, int(h * 0.93), w, int(h * 0.05))
                # Multi-color drop shadow tag
                p.setPen(AMBER)
                p.drawText(r.translated(6, 6), Qt.AlignmentFlag.AlignCenter, text)
                p.setPen(MAGENTA)
                p.drawText(r.translated(3, 3), Qt.AlignmentFlag.AlignCenter, text)
                p.setPen(RED)
                p.drawText(r.translated(2, 2), Qt.AlignmentFlag.AlignCenter, text)
                p.setPen(WHITE if self._hover else CYAN)
                p.drawText(r, Qt.AlignmentFlag.AlignCenter, text)
                self._btn_rect = QRect(int(w * 0.28), int(h * 0.92), int(w * 0.44), int(h * 0.07))
            else:
                self._btn_rect = QRect(0, 0, 0, 0)
            p.end()
            return
            # ---- legacy unreachable below ----
            # === 1) Deep space bg ===
            bg = QLinearGradient(0, 0, 0, h)
            bg.setColorAt(0.0, QColor(4, 6, 12))
            bg.setColorAt(0.5, QColor(2, 3, 8))
            bg.setColorAt(1.0, QColor(6, 4, 10))
            p.fillRect(0, 0, w, h, QBrush(bg))

            # === 2) Central reactor vignette glow ===
            vig = QRadialGradient(cx, cy, min(w, h) * 0.45)
            vig.setColorAt(0.0, QColor(0, 240, 255, 26))
            vig.setColorAt(0.4, QColor(0, 240, 255, 10))
            vig.setColorAt(1.0, QColor(0, 0, 0, 0))
            p.fillRect(0, 0, w, h, QBrush(vig))

            # === 3) MYCELIUM SEGMENTS — brown base + cyan glow overlay ===
            base_col = QColor(78, 40, 15)
            for s in self._segments:
                a = min(1.0, s['life'])
                base_col.setAlpha(int(160 * a))
                p.setPen(QPen(base_col, max(0.5, s['w'])))
                p.drawLine(QPointF(s['x1'], s['y1']), QPointF(s['x2'], s['y2']))
                if a > 0.55:
                    glow_a = int(240 * (a - 0.55) / 0.45)
                    p.setPen(QPen(QColor(0, 255, 213, glow_a), max(0.5, s['w'] * 0.72)))
                    p.drawLine(QPointF(s['x1'], s['y1']), QPointF(s['x2'], s['y2']))

            # === 4) Tip highlights ===
            for tp in self._tips:
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QBrush(QColor(0, 255, 213, 110)))
                p.drawEllipse(QPointF(tp['x'], tp['y']), 5, 5)
                p.setBrush(QBrush(QColor(255, 255, 255, 230)))
                p.drawEllipse(QPointF(tp['x'], tp['y']), 1.6, 1.6)

            # === 5) Nutrient shimmer ===
            t = self._frame / 30.0
            for n in self._nutr:
                a = int(70 + 60 * _m.sin(t * 3 + n['x'] * 0.01))
                p.setBrush(QBrush(QColor(0, 255, 213, a)))
                p.setPen(Qt.PenStyle.NoPen)
                p.drawEllipse(QPointF(n['x'], n['y']), 3, 3)
                p.setBrush(QBrush(QColor(0, 255, 213, 22)))
                p.drawEllipse(QPointF(n['x'], n['y']), 9, 9)

            # === 6) Reactor core pulse — hot white centre ===
            core_r = 8 + 4 * _m.sin(t * 4)
            core_g = QRadialGradient(cx, cy, core_r * 5)
            core_g.setColorAt(0.0, QColor(255, 255, 255, 255))
            core_g.setColorAt(0.25, QColor(0, 255, 213, 220))
            core_g.setColorAt(0.7, QColor(0, 90, 130, 60))
            core_g.setColorAt(1.0, QColor(0, 0, 0, 0))
            p.fillRect(int(cx - core_r * 5), int(cy - core_r * 5),
                       int(core_r * 10), int(core_r * 10), QBrush(core_g))

            # === 7) MASSIVE FULL-BLEED WORDMARK — top third, no boxes ===
            # Sized off screen height so 1080p, 1440p, 4K all read the same.
            title_h = int(h * 0.18)
            title_y = int(h * 0.20)
            title_rect = QRect(0, title_y, w, title_h)
            f_title = QFont('Impact', int(h * 0.18))
            f_title.setBold(True)
            f_title.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, int(h * 0.010))
            p.setFont(f_title)
            reveal_a = int(255 * self._reveal)
            # Deep cyan outer shadow — 3 offset layers for depth
            for off, a_mul in ((6, 0.10), (3, 0.20), (1, 0.35)):
                p.setPen(QColor(0, 255, 213, int(reveal_a * a_mul)))
                p.drawText(title_rect.translated(0, off), Qt.AlignmentFlag.AlignCenter, 'BM23-TOOLZ-SIFT')
            # Amber underlight
            p.setPen(QColor(255, 176, 0, int(reveal_a * 0.15)))
            p.drawText(title_rect.translated(0, -2), Qt.AlignmentFlag.AlignCenter, 'BM23-TOOLZ-SIFT')
            # White core
            p.setPen(QColor(255, 255, 255, reveal_a))
            p.drawText(title_rect, Qt.AlignmentFlag.AlignCenter, 'BM23-TOOLZ-SIFT')

            # Subtitle — spaced monospace under the wordmark
            f_sub = QFont('Consolas', int(h * 0.018), QFont.Weight.Bold)
            f_sub.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, int(h * 0.007))
            p.setFont(f_sub)
            p.setPen(QColor(0, 255, 213, int(230 * self._reveal)))
            p.drawText(QRect(0, title_y + title_h + int(h * 0.02), w, int(h * 0.04)),
                       Qt.AlignmentFlag.AlignCenter,
                       'MAILBOX      RECLAMATION      REACTOR')

            # Byline
            f_byline = QFont('Consolas', int(h * 0.011))
            f_byline.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, int(h * 0.004))
            p.setFont(f_byline)
            p.setPen(QColor(255, 176, 0, int(200 * self._reveal)))
            p.drawText(QRect(0, title_y + title_h + int(h * 0.065), w, int(h * 0.03)),
                       Qt.AlignmentFlag.AlignCenter,
                       f'v2.15.5    ·    {_BM23_BUILD_STAMP}    ·    bluemeanie23')

            # === 8) HORIZONTAL BOOT-LOG TICKER — one line, bottom ===
            f_log = QFont('Consolas', int(h * 0.014), QFont.Weight.Bold)
            f_log.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, int(h * 0.003))
            p.setFont(f_log)
            log_y_center = int(h * 0.80)
            row_h = int(h * 0.024)
            # Only the latest 3 lines visible in a stacked column, right-aligned
            recent = self._BOOT_LOG[max(0, self._boot_index - 3):self._boot_index]
            for i, entry in enumerate(recent):
                is_last = (i == len(recent) - 1) and (self._boot_index < len(self._BOOT_LOG))
                idx_from_end = len(recent) - 1 - i
                a_mul = 1.0 - idx_from_end * 0.28
                caret = '▶  ' if is_last else '✓  '
                col = QColor(0, 255, 213, int(255 * a_mul))
                if is_last:
                    col = QColor(255, 255, 255, 240)
                p.setPen(col)
                y_pos = log_y_center - (len(recent) - 1 - i) * row_h
                # Right-align via manual placement
                text = f'{caret}{entry}'
                fm = p.fontMetrics()
                tw = fm.horizontalAdvance(text)
                p.drawText(int(w * 0.5 - tw / 2), y_pos, text)

            # === 9) FULL-WIDTH PROGRESS BAR — bottom-centred ===
            prog_pct = self._boot_index / len(self._BOOT_LOG)
            prog_w = int(w * 0.44); prog_h = 3
            prog_x = int(w * 0.28); prog_y = int(h * 0.88)
            # Track
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QBrush(QColor(0, 255, 213, 40)))
            p.drawRect(prog_x, prog_y, prog_w, prog_h)
            # Fill
            fill = int(prog_w * prog_pct)
            grad = QLinearGradient(prog_x, 0, prog_x + fill, 0)
            grad.setColorAt(0.0, QColor(0, 255, 213, 200))
            grad.setColorAt(1.0, QColor(255, 255, 255, 255))
            p.fillRect(prog_x, prog_y, fill, prog_h, QBrush(grad))
            # Endcap dot
            if fill > 0:
                p.setBrush(QBrush(QColor(255, 255, 255, 240)))
                p.drawEllipse(QPointF(prog_x + fill, prog_y + prog_h / 2), 4, 4)
            # Percent label centred under bar
            f_pct = QFont('Consolas', int(h * 0.013)); f_pct.setBold(True)
            f_pct.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, int(h * 0.005))
            p.setFont(f_pct)
            p.setPen(QColor(0, 255, 213, 200))
            p.drawText(prog_x, prog_y + prog_h + 8, prog_w, int(h * 0.03),
                       Qt.AlignmentFlag.AlignCenter,
                       f'BOOT SEQUENCE    ·    {int(prog_pct * 100):3d}%')

            # === 10) ENTER PROMPT (no boxy button) — text with pulse halo ===
            btn_ready = self._boot_index >= len(self._BOOT_LOG)
            if btn_ready:
                # Halo behind text
                halo_pulse = 0.6 + 0.4 * _m.sin(t * 3)
                halo_r = int(w * 0.22 * halo_pulse)
                halo_g = QRadialGradient(cx, int(h * 0.63), halo_r)
                halo_g.setColorAt(0.0, QColor(0, 255, 213, int(70 * halo_pulse)))
                halo_g.setColorAt(0.7, QColor(0, 255, 213, 12))
                halo_g.setColorAt(1.0, QColor(0, 0, 0, 0))
                p.fillRect(int(cx - halo_r), int(h * 0.63 - halo_r / 2),
                           halo_r * 2, halo_r, QBrush(halo_g))
                f_enter = QFont('Impact', int(h * 0.05)); f_enter.setBold(True)
                f_enter.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, int(h * 0.020))
                p.setFont(f_enter)
                enter_col = QColor(255, 255, 255) if self._hover else QColor(0, 255, 213)
                p.setPen(enter_col)
                p.drawText(QRect(0, int(h * 0.60), w, int(h * 0.08)),
                           Qt.AlignmentFlag.AlignCenter, 'PRESS  ENTER  TO  BOOT')
                # Store hit rect for click detection — generous.
                self._btn_rect = QRect(int(w * 0.30), int(h * 0.58), int(w * 0.40), int(h * 0.12))
            else:
                self._btn_rect = QRect(0, 0, 0, 0)

            # === 11) CORNER TICKS (subtle, not boxy L-brackets) ===
            tick = 24; m = 24
            p.setPen(QPen(QColor(0, 255, 213, 220), 1.5))
            for bx, by, dx, dy in ((m, m, 1, 1), (w - m, m, -1, 1),
                                   (m, h - m, 1, -1), (w - m, h - m, -1, -1)):
                p.drawLine(bx, by, bx + dx * tick, by)
                p.drawLine(bx, by, bx, by + dy * tick)
                p.setBrush(QBrush(QColor(0, 255, 213, 200)))
                p.setPen(Qt.PenStyle.NoPen)
                p.drawEllipse(QPointF(bx, by), 2, 2)
                p.setPen(QPen(QColor(0, 255, 213, 220), 1.5))
                p.setBrush(Qt.BrushStyle.NoBrush)

            # === 12) FOOTER + ESC HINT — bottom edge ===
            f_foot = QFont('Consolas', int(h * 0.010))
            f_foot.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, int(h * 0.003))
            p.setFont(f_foot)
            p.setPen(QColor(255, 255, 255, 90))
            p.drawText(QRect(0, int(h * 0.96), w, int(h * 0.03)),
                       Qt.AlignmentFlag.AlignCenter,
                       'CLICK    ·    ENTER    ·    SPACE                            ESC  to  abort')
            p.end()
        except Exception:
            import traceback as _tb; _tb.print_exc()

    def mousePressEvent(self, e):
        try:
            if hasattr(self, '_btn_rect') and self._btn_rect.contains(e.pos()):
                self.enter_clicked.emit()
                return
        except Exception:
            pass
        super().mousePressEvent(e)

    def mouseMoveEvent(self, e):
        self._hover = hasattr(self, '_btn_rect') and self._btn_rect.contains(e.pos())
        self.update()

    def keyPressEvent(self, e):
        if e.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter, Qt.Key.Key_Space):
            self.enter_clicked.emit()
        elif e.key() == Qt.Key.Key_Escape:
            self.reject()


class _BM23BurstPopup(QWidget):
    """Comic-book explosive burst popup — country hits and system events.

    Kinds:
      'burst_hit'    — login-validated per-country hit (uses country palette)
      'burst_region' — user-selected country region trigger (same treatment,
                       distinct border tag)
      'event'        — neutral tool/app system event (cyan/magenta neutral)
    """

    WIDTH = 620
    HEIGHT = 360
    ENTRANCE_MS = 320
    EXIT_MS = 360
    _NUM_SPIKES = 22           # was 16 — jagged-er, more comic-punch
    _NUM_SMOKE = 9             # was 7 — thicker smoke curtain
    _SHOCKWAVE_RINGS = 3       # animated concentric rings behind the star

    def __init__(self, country_code=None, kind='burst_hit', extra_text='',
                 duration_ms=6500, on_closed=None, on_copy=None, parent=None):
        super().__init__(parent)
        self._kind = kind
        self._on_closed = on_closed
        self._on_copy = on_copy
        self._closing = False
        self._target_pos = QPoint(0, 0)
        self._duration_ms = max(1500, int(duration_ms))
        self._extra_text = str(extra_text or '')

        db = _bm23_get_country(country_code)
        if kind == 'event' or db is None:
            self._country_code = 'BM23' if kind == 'event' else (country_code or '??').upper()
            self._country_name = 'SYSTEM' if kind == 'event' else self._country_code
            self._palette = _BM23_EVENT_PALETTE
            self._words = _BM23_EVENT_WORDS
            self._flag_hint = 'none'
        else:
            self._country_code = (country_code or '').upper()
            self._country_name = db['name']
            self._palette = db['palette']
            self._words = db['words']
            self._flag_hint = db.get('flag_hint', 'none')

        # Border-tint override so region-trigger stands apart from login-hit
        # even with the same country palette.
        if kind == 'burst_region':
            self._tag_label = 'REGION HIT'
        elif kind == 'event':
            self._tag_label = 'SYSTEM'
        else:
            self._tag_label = 'HIT'

        self._anim_pos = None
        self._anim_opacity = None
        self._anim_scale = None
        self._smoke_phase = 0.0
        self._pulse_phase = 0.0

        self.setWindowFlags(
            Qt.WindowType.FramelessWindowHint
            | Qt.WindowType.WindowStaysOnTopHint
            | Qt.WindowType.Tool
        )
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self.setAttribute(Qt.WidgetAttribute.WA_ShowWithoutActivating, True)
        self.setFixedSize(self.WIDTH, self.HEIGHT)

        # Rebuild the star/emanating layout once per instance for stability
        # (subtle rotation per spawn keeps it visually fresh but positioning
        # of the interactive buttons stays predictable across the lifetime).
        self._rot_offset = _bm23_random.uniform(-0.18, 0.18)
        self._word_layout = self._build_word_layout()

        # Idle animator: pulses the smoke + drives subtle icon shake.
        self._idle_timer = _QTimer(self)
        self._idle_timer.timeout.connect(self._on_idle_tick)
        self._idle_timer.start(100)  # 10fps — smoke pulse doesn't need 20fps, halves CPU load

    # -- word emanation layout -------------------------------------------
    def _build_word_layout(self):
        """Pre-compute (word, x, y, angle_deg, font_size, alpha) for radial words."""
        layout = []
        cx, cy = self.WIDTH / 2, self.HEIGHT / 2
        n = min(len(self._words), 11)
        for i, word in enumerate(self._words[:n]):
            angle = (i / n) * 2 * _bm23_math.pi + self._rot_offset
            dist = _bm23_random.uniform(140, 250)
            x = cx + _bm23_math.cos(angle) * dist
            y = cy + _bm23_math.sin(angle) * dist
            deg = _bm23_math.degrees(angle) + 90
            # Bias rotation to a readable ±60° range
            while deg > 90: deg -= 180
            while deg < -90: deg += 180
            size = _bm23_random.randint(11, 20)
            alpha = _bm23_random.randint(70, 150)
            layout.append((word, x, y, deg, size, alpha))
        return layout

    # -- lifecycle -------------------------------------------------------
    def show_animated(self, target_pos):
        self._target_pos = QPoint(target_pos)
        self.move(self._target_pos)
        self.setWindowOpacity(0.0)
        self.show()
        self.raise_()

        # ---------- DOPAMINE PUMP ----------
        # 1) Fade in
        fade_in = QPropertyAnimation(self, b'windowOpacity', self)
        fade_in.setDuration(self.ENTRANCE_MS)
        fade_in.setStartValue(0.0)
        fade_in.setEndValue(1.0)
        fade_in.setEasingCurve(QEasingCurve.Type.OutCubic)
        fade_in.destroyed.connect(lambda: setattr(self, '_anim_opacity', None))
        fade_in.start(QPropertyAnimation.DeletionPolicy.DeleteWhenStopped)
        self._anim_opacity = fade_in

        # 2) Position punch — bounce the popup itself so it lands with impact
        punch_start = QPoint(self._target_pos.x(), self._target_pos.y() + 40)
        self.move(punch_start)
        pos_anim = QPropertyAnimation(self, b'pos', self)
        pos_anim.setDuration(420)
        pos_anim.setStartValue(punch_start)
        pos_anim.setEndValue(self._target_pos)
        pos_anim.setEasingCurve(QEasingCurve.Type.OutBounce)
        pos_anim.destroyed.connect(lambda: setattr(self, '_anim_pos', None))
        pos_anim.start(QPropertyAnimation.DeletionPolicy.DeleteWhenStopped)
        self._anim_pos = pos_anim

        # 3) Self-shake + 4) main-window shake + 5) flash — but ONLY if we're
        # not spamming (hard rate-limit gate). This is what killed the CPU:
        # popup floods triggered shake+flash+wiggle on every hit and the loops
        # stacked. Now: one burst per ~550ms, extras skipped.
        if _bm23_can_run_fx():
            _QTimer.singleShot(0, self._bm23_self_shake)
            _QTimer.singleShot(0, _bm23_trigger_screen_shake)
            _QTimer.singleShot(0, _bm23_flash_screen)

        _QTimer.singleShot(self._duration_ms, self._begin_dismiss)

    def _bm23_self_shake(self):
        """Rapid 300ms position wiggle so the popup itself buzzes on entrance."""
        try:
            base = QPoint(self._target_pos)
            self._shake_step = 0
            def _tick():
                if self._closing or self._shake_step >= 12:
                    return
                dx = _bm23_random.randint(-6, 6)
                dy = _bm23_random.randint(-6, 6)
                try:
                    self.move(base.x() + dx, base.y() + dy)
                except RuntimeError:
                    return
                self._shake_step += 1
                _QTimer.singleShot(24, _tick)
            _tick()
            # Snap back to exact position after shake
            _QTimer.singleShot(320, lambda: self.move(base) if not self._closing else None)
        except Exception:
            pass

    def _begin_dismiss(self):
        if self._closing:
            return
        self._closing = True
        fade = QPropertyAnimation(self, b'windowOpacity', self)
        fade.setDuration(self.EXIT_MS)
        fade.setStartValue(self.windowOpacity())
        fade.setEndValue(0.0)
        fade.setEasingCurve(QEasingCurve.Type.InCubic)
        fade.finished.connect(self.close)
        fade.destroyed.connect(lambda: setattr(self, '_anim_opacity', None))
        fade.start(QPropertyAnimation.DeletionPolicy.DeleteWhenStopped)
        self._anim_opacity = fade

    def _on_idle_tick(self):
        self._smoke_phase = (self._smoke_phase + 0.02) % 1.0
        self._pulse_phase = (self._pulse_phase + 0.06) % (2 * _bm23_math.pi)
        self.update()

    def closeEvent(self, event):
        try:
            self._idle_timer.stop()
        except Exception:
            pass
        if self._on_closed is not None:
            cb, self._on_closed = self._on_closed, None
            try:
                cb(self)
            except Exception:
                pass
        super().closeEvent(event)

    def mousePressEvent(self, event):
        # Right side = copy details; Bottom-right corner = close
        pos = event.pos()
        # Close button hotspot (top-right)
        if pos.x() > self.WIDTH - 40 and pos.y() < 40:
            self._begin_dismiss()
            return
        # Copy button hotspot (bottom-right)
        if pos.x() > self.WIDTH - 110 and pos.y() > self.HEIGHT - 44:
            if callable(self._on_copy):
                try:
                    self._on_copy(self)
                except Exception:
                    pass
            else:
                try:
                    _sp_imp_9d17.QApplication.clipboard().setText(self._extra_text or self._country_name)
                except Exception:
                    pass
            return
        super().mousePressEvent(event)

    # -- painting --------------------------------------------------------
    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        p.setRenderHint(QPainter.RenderHint.TextAntialiasing, True)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)

        cx, cy = self.WIDTH / 2, self.HEIGHT / 2

        # ---------- Layer 0: shockwave rings (bottom of stack) ----------
        try:
            _accent_hex = self._palette[1] if len(self._palette) > 1 else '#ff00a0'
            _wave_color = QColor(_accent_hex)
            for ring in range(self._SHOCKWAVE_RINGS):
                phase = (self._smoke_phase + ring / self._SHOCKWAVE_RINGS) % 1.0
                r = 60 + phase * 220
                alpha = int(140 * (1.0 - phase))
                _wave_color.setAlpha(alpha)
                p.setPen(QPen(_wave_color, 3))
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawEllipse(_QPointF(cx, cy), r, r)
        except Exception:
            pass

        # ---------- Layer 1: smoke puffs behind everything ----------
        for i in range(self._NUM_SMOKE):
            phase = (self._smoke_phase + i / self._NUM_SMOKE) % 1.0
            grow = 0.6 + phase * 0.5
            fade = int(80 * (1.0 - phase))
            r = 60 * grow
            ang = (i / self._NUM_SMOKE) * 2 * _bm23_math.pi + self._rot_offset * 3
            offset = 120 + phase * 40
            sx = cx + _bm23_math.cos(ang) * offset
            sy = cy + _bm23_math.sin(ang) * offset
            grad = QRadialGradient(sx, sy, r)
            grad.setColorAt(0.0, QColor(255, 255, 255, fade))
            grad.setColorAt(0.5, QColor(200, 200, 210, fade // 2))
            grad.setColorAt(1.0, QColor(80, 80, 100, 0))
            p.setBrush(QBrush(grad))
            p.setPen(Qt.PenStyle.NoPen)
            p.drawEllipse(_QPointF(sx, sy), r, r)

        # ---------- Layer 2: radial slogan words (background text) ----------
        p.save()
        for word, x, y, deg, size, alpha in self._word_layout:
            p.save()
            p.translate(x, y)
            p.rotate(deg)
            f = QFont('Impact', size)
            f.setBold(True)
            p.setFont(f)
            # Outline pass for readability
            p.setPen(QPen(QColor(0, 0, 0, min(255, alpha + 50)), 3))
            p.drawText(0, 0, word)
            p.setPen(QPen(QColor(255, 255, 255, alpha), 1))
            p.drawText(0, 0, word)
            p.restore()
        p.restore()

        # ---------- Layer 3: burst star (comic explosion) ----------
        primary = QColor(self._palette[0])
        secondary = QColor(self._palette[1])
        accent = QColor(self._palette[2]) if len(self._palette) > 2 else secondary
        text_hi = QColor(self._palette[3]) if len(self._palette) > 3 else QColor('#FFFFFF')

        pulse = 1.0 + 0.04 * _bm23_math.sin(self._pulse_phase)
        outer_r = 130 * pulse
        inner_r = 78 * pulse
        star = QPolygonF()
        for i in range(self._NUM_SPIKES * 2):
            angle = (i / (self._NUM_SPIKES * 2)) * 2 * _bm23_math.pi - _bm23_math.pi / 2 + self._rot_offset
            radius = outer_r if i % 2 == 0 else inner_r
            # Random jitter on outer points for jagged comic look
            if i % 2 == 0:
                radius *= _bm23_random.uniform(0.92, 1.08)
            px = cx + _bm23_math.cos(angle) * radius
            py = cy + _bm23_math.sin(angle) * radius
            star.append(_QPointF(px, py))

        # Outer shadow spike (thick black)
        p.setPen(QPen(QColor(0, 0, 0, 220), 6))
        p.setBrush(QBrush(QColor(0, 0, 0, 200)))
        shadow_star = QPolygonF([_QPointF(pt.x() + 4, pt.y() + 4) for pt in star])
        p.drawPolygon(shadow_star)

        # Main burst fill: gradient primary → secondary
        grad = QLinearGradient(cx - outer_r, cy - outer_r, cx + outer_r, cy + outer_r)
        grad.setColorAt(0.0, primary)
        grad.setColorAt(0.55, secondary)
        grad.setColorAt(1.0, primary.darker(140))
        p.setPen(QPen(QColor(0, 0, 0), 3))
        p.setBrush(QBrush(grad))
        p.drawPolygon(star)

        # Inner accent star (smaller, on top, accent color)
        inner_star = QPolygonF()
        for i in range(self._NUM_SPIKES * 2):
            angle = (i / (self._NUM_SPIKES * 2)) * 2 * _bm23_math.pi - _bm23_math.pi / 2 - self._rot_offset
            radius = (outer_r * 0.55) if i % 2 == 0 else (inner_r * 0.55)
            px = cx + _bm23_math.cos(angle) * radius
            py = cy + _bm23_math.sin(angle) * radius
            inner_star.append(_QPointF(px, py))
        p.setPen(QPen(QColor(0, 0, 0, 180), 1.5))
        p.setBrush(QBrush(accent))
        p.drawPolygon(inner_star)

        # ---------- Layer 4: country name + tag ----------
        self._draw_country_text(p, cx, cy, text_hi, secondary)

        # ---------- Layer 5: HUD chrome (tag pill + close X + copy button) ----------
        self._draw_hud(p, primary, accent, text_hi)

        p.end()

    def _draw_country_text(self, p, cx, cy, hi_color, shadow_color):
        name = self._country_name
        # Fit inside 70% width so BIG chunky text fills the burst star
        target_w = int(self.WIDTH * 0.62)
        # Try Impact + Arial Black + generic Sans — first available wins
        family = 'Impact'
        try:
            _families = QFontDatabase.families() if hasattr(QFontDatabase, 'families') else []
            for cand in ('Impact', 'Arial Black', 'Bebas Neue', 'Anton', 'Oswald'):
                if cand in _families:
                    family = cand
                    break
        except Exception:
            pass
        size = 82
        f = QFont(family, size)
        f.setBold(True)
        f.setStretch(QFont.Stretch.Condensed)
        f.setLetterSpacing(QFont.SpacingType.PercentageSpacing, 92)
        while size > 22:
            f.setPointSize(size)
            fm = QFontMetrics(f)
            if fm.horizontalAdvance(name) <= target_w:
                break
            size -= 3
        p.setFont(f)
        fm = QFontMetrics(f)
        text_w = fm.horizontalAdvance(name)
        text_h = fm.ascent()
        tx = cx - text_w / 2
        ty = cy + text_h / 2 - 6

        # Path once — used for stroke passes + gradient fill
        path = QPainterPath()
        path.addText(_QPointF(tx, ty), f, name)

        # 1) Chunky black outer stroke (comic book weight)
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.strokePath(path, QPen(QColor(0, 0, 0), 10, Qt.PenStyle.SolidLine,
                                Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))

        # 2) White knockout stroke (thin white line inside the black outline)
        p.strokePath(path, QPen(QColor(255, 255, 255), 4, Qt.PenStyle.SolidLine,
                                Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))

        # 3) Golden/warm gradient fill (matches the reference image warm interior)
        #    Uses hi_color at top → hot orange midway → deep red-orange bottom
        _top = QColor('#FFE28A')      # cream yellow highlight
        _mid = QColor('#FFB800')      # bright amber
        _bot = QColor('#E85A00')      # burnt orange
        # If country palette provides its own hi/text colour override, blend it
        try:
            _top = hi_color.lighter(140)
        except Exception:
            pass
        grad = QLinearGradient(0, ty - text_h, 0, ty + 6)
        grad.setColorAt(0.0, _top)
        grad.setColorAt(0.55, _mid)
        grad.setColorAt(1.0, _bot)
        p.fillPath(path, QBrush(grad))

        # 4) Inner white glaze on the top half (glossy sheen)
        gloss = QLinearGradient(0, ty - text_h, 0, ty - text_h / 3)
        gloss.setColorAt(0.0, QColor(255, 255, 255, 160))
        gloss.setColorAt(1.0, QColor(255, 255, 255, 0))
        p.save()
        p.setClipPath(path)
        p.fillRect(_QRectF(tx - 5, ty - text_h, text_w + 10, text_h * 0.55), QBrush(gloss))
        p.restore()

        # 5) Tiny cloud puffs left + right of the text (comic-book smoke dots)
        try:
            p.setPen(QPen(QColor(0, 0, 0), 2))
            p.setBrush(QBrush(QColor(255, 255, 255)))
            for dx in (-text_w / 2 - 30, text_w / 2 + 22):
                for i, (ox, oy, r) in enumerate([(0, 8, 8), (10, 2, 6), (-6, -4, 5)]):
                    p.drawEllipse(_QPointF(cx + dx + ox, ty - text_h / 2 + oy), r, r)
        except Exception:
            pass

        # 6) Small yellow stars scattered around the text
        try:
            p.setPen(QPen(QColor(0, 0, 0), 1.5))
            p.setBrush(QBrush(QColor('#FFDD44')))
            for star_off in [(-text_w / 2 - 18, -text_h + 6),
                              (text_w / 2 + 12, -text_h + 2),
                              (-text_w / 4, -text_h - 4),
                              (text_w / 3, text_h / 3)]:
                sx0 = cx + star_off[0]
                sy0 = ty + star_off[1]
                _star = QPolygonF()
                for j in range(10):
                    a = (j / 10) * 2 * _bm23_math.pi - _bm23_math.pi / 2
                    rr = 7 if j % 2 == 0 else 3
                    _star.append(_QPointF(sx0 + _bm23_math.cos(a) * rr,
                                           sy0 + _bm23_math.sin(a) * rr))
                p.drawPolygon(_star)
        except Exception:
            pass

    def _draw_hud(self, p, primary, accent, text_hi):
        # Tag pill top-left
        tag = self._tag_label
        f = QFont('Arial Black', 11)
        f.setBold(True)
        p.setFont(f)
        fm = QFontMetrics(f)
        tag_w = fm.horizontalAdvance(tag) + 22
        tag_rect = _QRectF(14, 12, tag_w, 26)
        p.setPen(QPen(QColor(0, 0, 0), 2))
        p.setBrush(QBrush(accent))
        p.drawRoundedRect(tag_rect, 6, 6)
        p.setPen(QPen(QColor(0, 0, 0), 1))
        p.drawText(tag_rect, Qt.AlignmentFlag.AlignCenter, tag)

        # Country code chip top-left below tag
        if self._country_code and self._country_code != 'BM23':
            code = self._country_code
            f2 = QFont('Consolas', 10)
            f2.setBold(True)
            p.setFont(f2)
            fm2 = QFontMetrics(f2)
            code_w = fm2.horizontalAdvance(code) + 16
            code_rect = _QRectF(14, 42, code_w, 20)
            p.setPen(QPen(QColor(0, 0, 0), 1.5))
            p.setBrush(QBrush(QColor(0, 0, 0, 200)))
            p.drawRoundedRect(code_rect, 4, 4)
            p.setPen(QPen(text_hi, 1))
            p.drawText(code_rect, Qt.AlignmentFlag.AlignCenter, code)

        # Close (X) top-right
        close_rect = _QRectF(self.WIDTH - 34, 12, 22, 22)
        p.setPen(QPen(QColor(0, 0, 0), 2))
        p.setBrush(QBrush(QColor(220, 30, 30)))
        p.drawRoundedRect(close_rect, 4, 4)
        f3 = QFont('Arial Black', 12)
        f3.setBold(True)
        p.setFont(f3)
        p.setPen(QPen(QColor(255, 255, 255), 1))
        p.drawText(close_rect, Qt.AlignmentFlag.AlignCenter, '✕')

        # Copy details button bottom-right
        copy_rect = _QRectF(self.WIDTH - 108, self.HEIGHT - 38, 96, 28)
        p.setPen(QPen(QColor(0, 0, 0), 2))
        p.setBrush(QBrush(QColor(20, 20, 30, 235)))
        p.drawRoundedRect(copy_rect, 6, 6)
        f4 = QFont('Arial Black', 10)
        f4.setBold(True)
        p.setFont(f4)
        p.setPen(QPen(text_hi, 1))
        p.drawText(copy_rect, Qt.AlignmentFlag.AlignCenter, 'COPY DETAILS')


class _BM23BurstManager(QObject):
    """Manager for burst popups — random screen positions, overlap avoidance."""

    MAX_VISIBLE = 3
    MIN_GAP = 60

    def __init__(self, parent=None):
        super().__init__(parent)
        self._active = []
        self._queue = deque()

    @classmethod
    def show_hit(cls, country_code, extra_text='', duration_ms=6500, on_copy=None):
        cls._instance()._enqueue('burst_hit', country_code, extra_text, duration_ms, on_copy)

    @classmethod
    def show_region(cls, country_code, extra_text='', duration_ms=6500, on_copy=None):
        cls._instance()._enqueue('burst_region', country_code, extra_text, duration_ms, on_copy)

    @classmethod
    def show_event(cls, message='', duration_ms=4500):
        cls._instance()._enqueue('event', None, message, duration_ms, None)

    @classmethod
    def _instance(cls):
        global _BM23_BURST_MANAGER
        if _BM23_BURST_MANAGER is None:
            _BM23_BURST_MANAGER = cls()
        return _BM23_BURST_MANAGER

    def _enqueue(self, kind, country_code, extra_text, duration_ms, on_copy):
        self._queue.append((kind, country_code, extra_text, duration_ms, on_copy))
        self._pump()

    def _pump(self):
        while self._queue and len(self._active) < self.MAX_VISIBLE:
            kind, cc, extra, dur, on_copy = self._queue.popleft()
            pop = _BM23BurstPopup(
                country_code=cc, kind=kind, extra_text=extra,
                duration_ms=dur, on_closed=self._popup_closed, on_copy=on_copy,
            )
            self._active.append(pop)
            pop.show_animated(self._random_position(pop))

    def _popup_closed(self, popup):
        try:
            self._active.remove(popup)
        except ValueError:
            pass
        try:
            popup.deleteLater()
        except Exception:
            pass
        self._pump()

    def _random_position(self, popup):
        screen = QGuiApplication.primaryScreen()
        if screen is not None:
            avail = screen.availableGeometry()
        else:
            avail = QRect(0, 0, 1920, 1080)
        margin = 30
        for _ in range(20):
            x = _bm23_random.randint(avail.left() + margin,
                                     max(avail.left() + margin, avail.right() - popup.WIDTH - margin))
            y = _bm23_random.randint(avail.top() + margin,
                                     max(avail.top() + margin, avail.bottom() - popup.HEIGHT - margin))
            candidate = QRect(x, y, popup.WIDTH, popup.HEIGHT)
            collision = False
            for other in self._active:
                if other is popup:
                    continue
                try:
                    other_rect = QRect(other.pos(), other.size())
                    if candidate.intersects(other_rect.adjusted(-self.MIN_GAP, -self.MIN_GAP,
                                                                 self.MIN_GAP, self.MIN_GAP)):
                        collision = True
                        break
                except RuntimeError:
                    continue
            if not collision:
                return QPoint(x, y)
        # Fallback: just pick something in the top-right quadrant
        return QPoint(avail.right() - popup.WIDTH - margin, avail.top() + margin)


_BM23_BURST_MANAGER = None
BM23BurstManager = _BM23BurstManager


__all__ = ["BM23PopupManager", "BM23BurstManager"]



# ============================================================
# BM23 SPLASH / LOADING SCREEN (inlined — single-file build)
# ============================================================
"""
bm23_splash — HOTMAIL CHECKER // BM23-TOOLZ splash / loading screen.

Self-contained, pure PyQt6 (QtCore / QtGui / QtWidgets) + stdlib math/random.
No external assets, no WebEngine. Import-safe: zero side effects at import time.

Public API:
    splash = _BM23SplashScreen()
    splash.show()
    splash.log("initializing modules ...")
    splash.set_progress(63)
    splash.done.connect(app.quit)
    splash.finish()          # fades out over ~400 ms, closes, emits done
"""

import math
import random

from PyQt6.QtCore import Qt, QTimer, pyqtSignal, QPropertyAnimation, QRectF, QPointF
from PyQt6.QtGui import (
    QPainter,
    QColor,
    QFont,
    QPen,
    QPainterPath,
    QLinearGradient,
)
from PyQt6.QtWidgets import QWidget, QApplication

# ---------------------------------------------------------------------------
# Splash palette — matches the MAILBOX RECLAMATION REACTOR main app.
# Primary = cyan, secondary = red, tertiary = amber; bg = deep-space navy.
# ---------------------------------------------------------------------------
C_BG        = QColor("#02020a")   # deep space navy (matches reactor bg)
C_BG2       = QColor("#08122c")   # lifted panel tone
C_GREEN     = QColor("#00f0ff")   # PRIMARY = reactor cyan
C_CYAN      = QColor("#93c5fd")   # softer cyan (secondary accents)
C_MAGENTA   = QColor("#ff2040")   # reactor red (was magenta)
C_AMBER     = QColor("#ffb000")   # amber warnings

# Splash sizes computed at runtime from the primary screen so the splash
# fills the whole display. Fallback defaults if no QApplication exists yet.
WIN_W, WIN_H = 1920, 1080
CORNER_R     = 0.0                # fullscreen — no rounded corners
TICK_MS      = 33                 # ~30 fps
LOG_LINES    = 8

# Globe geometry — recomputed once WIN_W/WIN_H are known
GLOBE_CX     = WIN_W / 2.0
GLOBE_CY     = WIN_H * 0.48
GLOBE_R      = 220.0
GLOBE_TILT   = math.radians(18.0)  # axial tilt for style


def _dim(color: QColor, alpha: int) -> QColor:
    """Copy of *color* with a new alpha (0-255)."""
    c = QColor(color)
    c.setAlpha(max(0, min(255, int(alpha))))
    return c


def _mono_font(size, bold: bool = False) -> QFont:
    """Monospace font with Consolas -> Cascadia Code fallback chain."""
    f = QFont()
    try:
        f.setFamilies(["Consolas", "Cascadia Code", "Courier New", "monospace"])
    except AttributeError:  # very old Qt6 fallback
        f.setFamily("Consolas")
    if isinstance(size, float):
        f.setPointSizeF(size)
    else:
        f.setPointSize(int(size))
    f.setBold(bold)
    f.setStyleHint(QFont.StyleHint.TypeWriter)
    return f


class _BM23SplashScreen(QWidget):
    """Frameless neon splash screen with rotating dot-globe, scanline,
    boot log and progress bar."""

    done = pyqtSignal()

    def __init__(self, parent: QWidget | None = None) -> None:
        super().__init__(
            parent,
            Qt.WindowType.FramelessWindowHint
            | Qt.WindowType.WindowStaysOnTopHint
            | Qt.WindowType.SplashScreen,
        )
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        # Fullscreen sizing off the primary screen
        global WIN_W, WIN_H, GLOBE_CX, GLOBE_CY, GLOBE_R
        try:
            app = QApplication.instance()
            if app is not None:
                screen = app.primaryScreen()
                if screen is not None:
                    geo = screen.geometry()
                    WIN_W = geo.width(); WIN_H = geo.height()
                    GLOBE_CX = WIN_W / 2.0
                    GLOBE_CY = WIN_H * 0.48
                    GLOBE_R  = min(WIN_W, WIN_H) * 0.22
        except Exception:
            pass
        self.setFixedSize(WIN_W, WIN_H)
        self._center_on_screen()
        # Pre-baked starfield + chroma spots + particle mesh for full-page bg
        import random as _rnd
        self._rand = _rnd.Random(31337)
        self._stars = []
        for _ in range(900):
            depth = self._rand.random()
            self._stars.append((
                self._rand.random(),           # x_norm
                self._rand.random(),           # y_norm
                0.4 + depth * 2.4,             # radius
                50 + int(depth * 200),         # base alpha
                self._rand.random() * 6.283,   # twinkle phase
                depth,                          # parallax depth
                self._rand.random() > 0.55,    # warm vs cool
            ))
        self._chroma = [
            (0.20, 0.30,   0, 240, 255, 60, 0.34, 0.006),
            (0.82, 0.28, 255,  40,  60, 70, 0.36, 0.005),
            (0.30, 0.78, 255,   0, 160, 44, 0.32, 0.007),
            (0.78, 0.80,  60, 255, 200, 34, 0.30, 0.004),
            (0.50, 0.05, 255, 180,  60, 34, 0.28, 0.005),
            (0.50, 0.95, 180,  60, 255, 32, 0.32, 0.003),
        ]
        self._parts = []
        for _ in range(120):
            self._parts.append({
                'x': self._rand.random(),
                'y': self._rand.random(),
                'vx': (self._rand.random() - 0.5) * 0.0004,
                'vy': (self._rand.random() - 0.5) * 0.0004,
                'r': 0.6 + self._rand.random() * 1.6,
                'hot': self._rand.random() < 0.55,
            })

        # ---- state ------------------------------------------------------
        self._tick       = 0            # animation frame counter
        self._rot        = 0.0          # globe rotation angle (radians)
        self._scan_y     = -30.0        # scanline position
        self._progress   = 0            # 0..100
        self._log: list[str] = []
        self._finishing  = False
        self._fade: QPropertyAnimation | None = None

        # ---- globe graticule: unit-sphere points (lat circles + meridians)
        self._grid_pts: list[tuple[float, float, float]] = []
        for lat in range(-75, 76, 15):
            for lon in range(0, 360, 10):
                self._grid_pts.append(self._sph(lat, lon))
        for lon in range(0, 360, 30):
            for la in range(-88, 89, 8):
                self._grid_pts.append(self._sph(la, lon))

        # ---- pulsing "hit" markers on the globe surface -----------------
        rng = random.Random(0xB423)
        self._hits = []
        for _ in range(5):
            lat = rng.uniform(-60, 60)
            lon = rng.uniform(0, 360)
            self._hits.append(
                {
                    "v":     self._sph(lat, lon),
                    "phase": rng.uniform(0, math.tau),
                    "speed": rng.uniform(0.06, 0.14),
                    "col":   C_MAGENTA if rng.random() < 0.5 else C_GREEN,
                }
            )

        # ---- animation timer --------------------------------------------
        self._timer = QTimer(self)
        self._timer.setInterval(TICK_MS)
        self._timer.timeout.connect(self._on_tick)
        self._timer.start()

    # ------------------------------------------------------------------ #
    # Public API                                                          #
    # ------------------------------------------------------------------ #
    def set_progress(self, pct: int) -> None:
        """Set progress bar percentage (clamped 0-100)."""
        self._progress = max(0, min(100, int(pct)))
        self.update()

    def log(self, line: str) -> None:
        """Append a line to the boot log (only the last few are shown)."""
        self._log.append(str(line))
        if len(self._log) > 64:  # bound memory; display uses last LOG_LINES
            self._log = self._log[-64:]
        self.update()

    def finish(self) -> None:
        """Fade the window out over ~400 ms, then close() and emit done()."""
        if self._finishing:
            return
        self._finishing = True
        anim = QPropertyAnimation(self, b"windowOpacity", self)
        anim.setDuration(400)
        anim.setStartValue(self.windowOpacity())
        anim.setEndValue(0.0)

        def _on_faded() -> None:
            self.close()
            self.done.emit()

        anim.finished.connect(_on_faded)
        anim.start(QPropertyAnimation.DeletionPolicy.DeleteWhenStopped)
        self._fade = anim

    # ------------------------------------------------------------------ #
    # Internals                                                           #
    # ------------------------------------------------------------------ #
    def _center_on_screen(self) -> None:
        app = QApplication.instance()
        if app is None:
            return
        screen = app.primaryScreen()
        if screen is None:
            return
        geo = screen.availableGeometry()
        self.move(
            geo.center().x() - WIN_W // 2,
            geo.center().y() - WIN_H // 2,
        )

    @staticmethod
    def _sph(lat_deg: float, lon_deg: float) -> tuple[float, float, float]:
        """Lat/lon (degrees) -> unit sphere coords (y = up)."""
        la = math.radians(lat_deg)
        lo = math.radians(lon_deg)
        return (
            math.cos(la) * math.cos(lo),
            math.sin(la),
            math.cos(la) * math.sin(lo),
        )

    def _project(self, v: tuple[float, float, float]):
        """Rotate + tilt + orthographic project. Returns (sx, sy, depth)."""
        x, y, z = v
        ca, sa = math.cos(self._rot), math.sin(self._rot)
        xr = x * ca + z * sa
        zr = -x * sa + z * ca
        ct, st = math.cos(GLOBE_TILT), math.sin(GLOBE_TILT)
        yt = y * ct - zr * st
        zt = y * st + zr * ct
        return (
            GLOBE_CX + GLOBE_R * xr,
            GLOBE_CY - GLOBE_R * yt,
            zt,  # +1 = front, -1 = back
        )

    def _on_tick(self) -> None:
        self._tick += 1
        self._rot += 0.022
        self._scan_y += 3.4
        if self._scan_y > WIN_H + 30:
            self._scan_y = -30.0
        self.update()

    # ------------------------------------------------------------------ #
    # Painting                                                            #
    # ------------------------------------------------------------------ #
    def paintEvent(self, event) -> None:  # noqa: N802 (Qt naming)
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        p.setRenderHint(QPainter.RenderHint.TextAntialiasing, True)

        rect = QRectF(1.0, 1.0, WIN_W - 2.0, WIN_H - 2.0)
        path = QPainterPath()
        path.addRoundedRect(rect, CORNER_R, CORNER_R)

        # -- background ---------------------------------------------------
        bg = QLinearGradient(0, 0, 0, WIN_H)
        bg.setColorAt(0.0, C_BG2)
        bg.setColorAt(0.25, C_BG)
        bg.setColorAt(1.0, C_BG)
        p.fillPath(path, bg)

        # clipped interior FX (grid + scanline)
        p.save()
        p.setClipPath(path)
        self._draw_grid(p)
        self._draw_scanline(p)
        p.restore()

        # -- border: layered glow -----------------------------------------
        for width, alpha in ((7, 18), (4, 45), (1.4, 200)):
            p.setPen(QPen(_dim(C_GREEN, alpha), width))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(path)

        self._draw_corner_brackets(p)
        self._draw_header(p)
        self._draw_globe(p)
        self._draw_log(p)
        self._draw_progress(p)

        p.end()

    def _draw_grid(self, p: QPainter) -> None:
        """Full-page reactor bg — 900-star field + 6 drifting chroma spots
        + 120-node particle mesh with connective lines. Replaces the old
        grid so the splash reads as the same cinematic bg as the reactor."""
        from PyQt6.QtGui import QRadialGradient
        w, h = WIN_W, WIN_H
        t = self._tick / 30.0
        # 1) Chroma spots (soft drifting blobs)
        for i, (bfx, bfy, cr, cg, cb, ca, sz, sp) in enumerate(self._chroma):
            fx = (bfx + 0.08 * math.sin(t * sp + i)) % 1.0
            fy = (bfy + 0.06 * math.cos(t * (sp * 1.3) + i * 1.7)) % 1.0
            g = QRadialGradient(w * fx, h * fy, max(w, h) * sz)
            g.setColorAt(0.0, QColor(cr, cg, cb, ca))
            g.setColorAt(0.55, QColor(cr, cg, cb, max(0, ca // 3)))
            g.setColorAt(1.0, QColor(2, 2, 10, 0))
            p.fillRect(0, 0, w, h, QBrush(g))
        # 2) Starfield — parallax drift + twinkle
        p.setPen(Qt.PenStyle.NoPen)
        for sx, sy, sr, sa, sp, depth, warm in self._stars:
            tw = 0.5 + 0.5 * math.sin(sp + t * (0.6 + depth * 1.6))
            a = int(min(255, sa * tw))
            drift = t * 0.008 * (0.2 + depth)
            px = ((sx + drift) % 1.0) * w
            py = sy * h
            col = QColor(255, 140 + int(80 * tw), 160, a) if warm else QColor(120, 220, 255, a)
            p.setBrush(QBrush(col))
            p.drawEllipse(int(px - sr), int(py - sr), int(sr * 2), int(sr * 2))
        # 3) Particle mesh with connective lines when close
        pts = []
        for pt in self._parts:
            pt['x'] += pt['vx']; pt['y'] += pt['vy']
            if pt['x'] < 0 or pt['x'] > 1: pt['vx'] *= -1
            if pt['y'] < 0 or pt['y'] > 1: pt['vy'] *= -1
            pts.append((pt['x'] * w, pt['y'] * h, pt['r'], pt['hot']))
        for px, py, pr, hot in pts:
            col = QColor(255, 60, 90, 180) if hot else QColor(0, 240, 255, 180)
            p.setBrush(QBrush(col))
            p.drawEllipse(int(px - pr), int(py - pr), int(pr * 2), int(pr * 2))
        # Connective lines only for close pairs — cheap N² skip using stride
        n = len(pts)
        for i in range(0, n, 2):
            ax, ay, _, ahot = pts[i]
            for j in range(i + 1, min(i + 12, n)):
                bx, by, _, _ = pts[j]
                dx, dy = ax - bx, ay - by
                d2 = dx * dx + dy * dy
                if d2 < 22000:
                    a = int(90 * (1.0 - (d2 / 22000)))
                    col = QColor(255, 60, 90, a) if ahot else QColor(0, 240, 255, a)
                    p.setPen(QPen(col, 0.6))
                    p.drawLine(int(ax), int(ay), int(bx), int(by))
        p.setPen(Qt.PenStyle.NoPen)

    def _draw_scanline(self, p: QPainter) -> None:
        y = self._scan_y
        band = QLinearGradient(0, y - 18, 0, y + 18)
        band.setColorAt(0.0, _dim(C_GREEN, 0))
        band.setColorAt(0.5, _dim(C_GREEN, 40))
        band.setColorAt(1.0, _dim(C_GREEN, 0))
        p.fillRect(QRectF(0, y - 18, WIN_W, 36), band)
        p.setPen(QPen(_dim(C_CYAN, 90), 1))
        p.drawLine(QPointF(0, y), QPointF(WIN_W, y))

    def _draw_corner_brackets(self, p: QPainter) -> None:
        p.setPen(QPen(_dim(C_CYAN, 220), 2))
        L, m = 16, 8
        for cx, cy, dx, dy in (
            (m, m, 1, 1),
            (WIN_W - m, m, -1, 1),
            (m, WIN_H - m, 1, -1),
            (WIN_W - m, WIN_H - m, -1, -1),
        ):
            p.drawLine(cx, cy, cx + dx * L, cy)
            p.drawLine(cx, cy, cx, cy + dy * L)

    def _draw_header(self, p: QPainter) -> None:
        # HUGE wordmark near top-center — fullscreen scale
        _title_y = int(WIN_H * 0.10)
        title_rect = QRectF(0, _title_y, WIN_W, 140)
        p.setFont(_mono_font(112, bold=True))
        p.setPen(_dim(C_CYAN, 80))
        p.drawText(title_rect.translated(5, 5), Qt.AlignmentFlag.AlignHCenter, "SIFT")
        p.setPen(_dim(C_MAGENTA, 70))
        p.drawText(title_rect.translated(-5, -5), Qt.AlignmentFlag.AlignHCenter, "SIFT")
        p.setPen(C_GREEN)
        p.drawText(title_rect, Qt.AlignmentFlag.AlignHCenter, "SIFT")
        # Sub-title
        p.setFont(_mono_font(22, bold=True))
        p.setPen(C_GREEN)
        p.drawText(QRectF(0, _title_y + 130, WIN_W, 32),
                   Qt.AlignmentFlag.AlignHCenter,
                   "MAILBOX  ·  RECLAMATION  ·  REACTOR")
        # Byline
        p.setFont(_mono_font(13, bold=False))
        p.setPen(_dim(C_AMBER, 220))
        p.drawText(QRectF(0, _title_y + 168, WIN_W, 20),
                   Qt.AlignmentFlag.AlignHCenter,
                   "BM23-TOOLZ    //    brought to you by bluemeanie23")
        # Divider — long gradient line under the byline
        p.setPen(QPen(_dim(C_GREEN, 50), 1))
        p.drawLine(int(WIN_W * 0.25), _title_y + 200, int(WIN_W * 0.75), _title_y + 200)
        p.setPen(QPen(_dim(C_MAGENTA, 180), 1))
        p.drawLine(WIN_W // 2 - 80, _title_y + 200, WIN_W // 2 + 80, _title_y + 200)

    def _draw_globe(self, p: QPainter) -> None:
        # outer glow rings
        p.setBrush(Qt.BrushStyle.NoBrush)
        for r_extra, alpha in ((14, 26), (7, 70), (2, 150)):
            p.setPen(QPen(_dim(C_CYAN, alpha), 1))
            p.drawEllipse(
                QPointF(GLOBE_CX, GLOBE_CY),
                GLOBE_R + r_extra,
                GLOBE_R + r_extra,
            )

        # wireframe dots (front bright green, back dim teal)
        for v in self._grid_pts:
            sx, sy, z = self._project(v)
            if z >= 0:
                alpha = 70 + int(150 * z)
                col = _dim(C_GREEN, alpha)
            else:
                col = _dim(C_CYAN, 26 + int(26 * (z + 1)))
            p.setPen(QPen(col, 2, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            p.drawPoint(QPointF(sx, sy))

        # pulsing hit markers
        for hit in self._hits:
            sx, sy, z = self._project(hit["v"])
            if z < 0.05:
                continue
            pulse = 0.5 + 0.5 * math.sin(self._tick * hit["speed"] * 6 + hit["phase"])
            col = hit["col"]
            # expanding ring
            ring_r = 4.0 + 7.0 * pulse
            p.setPen(QPen(_dim(col, int(170 * (1 - pulse) * z)), 1.4))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawEllipse(QPointF(sx, sy), ring_r, ring_r)
            # core dot
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(_dim(col, int(230 * z)))
            p.drawEllipse(QPointF(sx, sy), 2.6, 2.6)

    def _draw_log(self, p: QPainter) -> None:
        # Bottom-left corner boot log, scaled up for fullscreen visibility.
        p.setFont(_mono_font(13))
        x = 60.0; y0 = WIN_H - 220.0; lh = 22.0
        lines = self._log[-LOG_LINES:]
        n = len(lines)
        for i, line in enumerate(lines):
            newest = i == n - 1
            age = n - 1 - i  # 0 = newest
            alpha = 235 if newest else max(55, 150 - age * 22)
            p.setPen(_dim(C_GREEN, alpha))
            prefix = "» " if newest else "  "
            text = prefix + line
            p.drawText(QPointF(x, y0 + i * lh), text)
            if newest and (self._tick // 8) % 2 == 0:
                # blinking block cursor after the newest line
                fm = p.fontMetrics()
                cx = x + fm.horizontalAdvance(text) + 4
                p.fillRect(QRectF(cx, y0 + i * lh - 10, 8, 12), _dim(C_CYAN, 220))

        # if log is empty, still show a blinking idle cursor
        if not lines and (self._tick // 8) % 2 == 0:
            p.fillRect(QRectF(x, y0 - 10, 8, 12), _dim(C_CYAN, 220))

    def _draw_progress(self, p: QPainter) -> None:
        # Full-width progress bar pinned near bottom of the fullscreen splash
        bx, by, bw, bh = 60.0, WIN_H - 90.0, WIN_W - 120.0, 18.0

        # status line above the bar
        p.setFont(_mono_font(12))
        p.setPen(_dim(C_AMBER, 220))
        p.drawText(QPointF(bx, by - 12), "SYS.BOOT   ::   SEC-CHANNEL ESTABLISHED")
        p.setPen(_dim(C_CYAN, 200))
        ver = "SIFT  v2.15.5   //   x64"
        fm = p.fontMetrics()
        p.drawText(QPointF(bx + bw - fm.horizontalAdvance(ver), by - 12), ver)

        # track
        track = QPainterPath()
        track.addRoundedRect(QRectF(bx, by, bw, bh), 4, 4)
        p.fillPath(track, _dim(C_BG2, 220))
        p.setPen(QPen(_dim(C_CYAN, 120), 1))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawPath(track)

        # neon fill
        frac = self._progress / 100.0
        if frac > 0:
            fw = max(6.0, bw * frac)
            fill = QLinearGradient(bx, 0, bx + fw, 0)
            fill.setColorAt(0.0, _dim(C_GREEN, 235))
            fill.setColorAt(1.0, _dim(C_CYAN, 235))
            fill_path = QPainterPath()
            fill_path.addRoundedRect(QRectF(bx + 1.5, by + 1.5, fw - 3, bh - 3), 3, 3)
            # glow underlay then fill
            p.fillPath(fill_path, _dim(C_GREEN, 45))
            p.fillPath(fill_path, fill)
            # bright leading edge
            p.setPen(QPen(C_CYAN, 2))
            p.drawLine(QPointF(bx + fw - 2, by + 2), QPointF(bx + fw - 2, by + bh - 2))

        # percentage
        p.setFont(_mono_font(9, bold=True))
        pct_txt = f"{self._progress:3d}%"
        p.setPen(C_BG if frac > 0.5 else C_GREEN)
        p.drawText(QRectF(bx, by - 1, bw, bh + 2),
                   Qt.AlignmentFlag.AlignHCenter | Qt.AlignmentFlag.AlignVCenter,
                   pct_txt)


