class _CornerPanel(QFrame):
    """Panel with 4 corner L-brackets + top-glow shine sweep (ultra.html style).
    Panels are semi-transparent so the reactor bg (starfield/plasma/rings)
    reads through — the bg is the star of the show, panels ride on top."""
    def __init__(self, red=False, parent=None):
        super().__init__(parent)
        self._red = red
        self._shine_t = 0
        self.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, True)
        col = '255,32,64' if red else '0,240,255'
        bg1 = 'rgba(35,5,10,0.35)' if red else 'rgba(10,15,30,0.35)'
        bg2 = 'rgba(15,3,5,0.55)' if red else 'rgba(4,4,15,0.55)'
        self.setStyleSheet(
            f"background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 {bg1}, stop:1 {bg2});"
            f"border: 1px solid rgba({col},0.24);"
        )
        self._shine_timer = QTimer(self)
        self._shine_timer.timeout.connect(self._advance_shine)
        self._shine_timer.start(60)

    def _advance_shine(self):
        self._shine_t = (self._shine_t + 1) % 240
        self.update()

    def paintEvent(self, ev):
        super().paintEvent(ev)
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        w = self.width(); h = self.height()
        # Top shine sweep — cyan/red streak crossing every ~4 sec
        col_line = QColor(255, 32, 64, 200) if self._red else QColor(0, 240, 255, 200)
        pos = (self._shine_t / 240.0) * (w + 200) - 100
        sg = QLinearGradient(pos - 80, 0, pos + 80, 0)
        sg.setColorAt(0.0, QColor(col_line.red(), col_line.green(), col_line.blue(), 0))
        sg.setColorAt(0.5, col_line)
        sg.setColorAt(1.0, QColor(col_line.red(), col_line.green(), col_line.blue(), 0))
        p.fillRect(0, 0, w, 2, QBrush(sg))
        # Corner L-brackets
        p.setRenderHint(QPainter.RenderHint.Antialiasing, False)
        col = QColor(255, 32, 64, 190) if self._red else QColor(0, 240, 255, 190)
        pen = QPen(col); pen.setWidth(2); p.setPen(pen)
        s = 12; m = 4
        p.drawLine(m, m, m + s, m); p.drawLine(m, m, m, m + s)
        p.drawLine(w - m - s, m, w - m, m); p.drawLine(w - m, m, w - m, m + s)
        p.drawLine(m, h - m, m + s, h - m); p.drawLine(m, h - m - s, m, h - m)
        p.drawLine(w - m - s, h - m, w - m, h - m); p.drawLine(w - m, h - m - s, w - m, h - m)


class _Thinker(QWidget):
    """3-dot pulsing indicator — shown next to RESULTS meta when running."""
    def __init__(self, color='#00f0ff', parent=None):
        super().__init__(parent)
        self.setFixedSize(30, 12)
        self._t = 0.0
        self._color = QColor(color)
        self._active = False
        self._timer = QTimer(self)
        self._timer.timeout.connect(self._tick)
        self._timer.start(80)

    def set_active(self, on):
        self._active = bool(on)
        self.update()

    def _tick(self):
        self._t += 0.16
        if self._active:
            self.update()

    def paintEvent(self, ev):
        import math
        p = QPainter(self); p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        if not self._active:
            p.setBrush(QBrush(QColor(self._color.red(), self._color.green(), self._color.blue(), 40)))
            p.setPen(Qt.PenStyle.NoPen)
            for i in range(3):
                p.drawEllipse(i * 10 + 2, 4, 4, 4)
            return
        for i in range(3):
            phase = self._t - i * 0.35
            amp = 0.4 + 0.6 * max(0, math.sin(phase))
            r = 2 + int(3 * amp)
            a = int(90 + 165 * amp)
            p.setBrush(QBrush(QColor(self._color.red(), self._color.green(), self._color.blue(), a)))
            p.setPen(Qt.PenStyle.NoPen)
            p.drawEllipse(i * 10 + 2 - (r - 2), 6 - r, r * 2, r * 2)


class _SweepLine(QWidget):
    """Horizontal shine line drifting from left to right — overlays reader body."""
    def __init__(self, color='#00f0ff', parent=None):
        super().__init__(parent)
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        self._color = QColor(color)
        self._t = 0.0
        self._timer = QTimer(self); self._timer.timeout.connect(self._tick); self._timer.start(45)

    def _tick(self):
        self._t = (self._t + 0.008) % 1.4
        self.update()

    def paintEvent(self, ev):
        p = QPainter(self); p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        w = self.width(); h = self.height()
        if w <= 0 or h <= 0:
            return
        pos = self._t * (w + 200) - 100
        sg = QLinearGradient(pos - 100, 0, pos + 100, 0)
        sg.setColorAt(0.0, QColor(self._color.red(), self._color.green(), self._color.blue(), 0))
        sg.setColorAt(0.5, QColor(self._color.red(), self._color.green(), self._color.blue(), 120))
        sg.setColorAt(1.0, QColor(self._color.red(), self._color.green(), self._color.blue(), 0))
        p.fillRect(0, max(0, h // 2 - 1), w, 2, QBrush(sg))


class _LogoOrb(QWidget):
    """Reactor sphere — deep-blue plasma core + 3 satellites orbiting on
    tilted planes + pulsing halo ring. Cyan/electric-blue palette."""
    def __init__(self, size=48, parent=None):
        super().__init__(parent)
        self.setFixedSize(size, size)
        self._sz = size
        self._t = 0.0
        self._timer = QTimer(self)
        self._timer.timeout.connect(self._tick_orb)
        self._timer.start(40)

    def _tick_orb(self):
        self._t += 0.05
        self.update()

    def paintEvent(self, ev):
        import math
        from PyQt6.QtGui import QRadialGradient
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        s = self._sz
        cx = s / 2; cy = s / 2
        pulse = 0.5 + 0.5 * math.sin(self._t * 1.8)
        # 1) Expanding halo ring (cyan) — one cycle every ~2s
        ring_r = s * 0.42 + s * 0.42 * ((self._t * 0.6) % 1.0)
        ring_alpha = int(140 * (1.0 - (self._t * 0.6) % 1.0))
        pen = QPen(QColor(0, 240, 255, ring_alpha)); pen.setWidthF(1.6); p.setPen(pen)
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawEllipse(int(cx - ring_r), int(cy - ring_r), int(ring_r * 2), int(ring_r * 2))
        # 2) Core sphere — cyan → deep blue radial
        orb_r = s * 0.38
        rg = QRadialGradient(cx - s * 0.10, cy - s * 0.10, orb_r * 1.3)
        rg.setColorAt(0.00, QColor(180, 245, 255, 255))
        rg.setColorAt(0.30, QColor( 60, 190, 255, int(220 + 30 * pulse)))
        rg.setColorAt(0.65, QColor( 20,  80, 200, 200))
        rg.setColorAt(0.95, QColor(  4,  20,  60, 160))
        rg.setColorAt(1.00, QColor(  2,   2,  10,   0))
        p.setBrush(QBrush(rg)); p.setPen(Qt.PenStyle.NoPen)
        p.drawEllipse(int(cx - orb_r), int(cy - orb_r), int(orb_r * 2), int(orb_r * 2))
        # 3) Inner shimmer highlight
        p.setBrush(QBrush(QColor(220, 250, 255, int(80 + 100 * pulse))))
        p.drawEllipse(int(cx - orb_r * 0.55), int(cy - orb_r * 0.80), int(orb_r * 0.42), int(orb_r * 0.32))
        # 4) Three orbiting satellites on tilted planes
        sat_r = s * 0.48
        colors = (QColor(0, 240, 255), QColor(120, 200, 255), QColor(0, 180, 220))
        for i, col in enumerate(colors):
            phase = self._t * (0.85 + i * 0.22) + i * 2.09
            tilt  = 0.35 + i * 0.28
            x = math.cos(phase) * sat_r
            y = math.sin(phase) * sat_r * math.cos(tilt)
            # Draw fainter when behind (based on sin phase)
            behind = (math.sin(phase) * math.sin(tilt)) < 0
            a = 100 if behind else 220
            dot_r = 2.0 if behind else 2.8
            col2 = QColor(col.red(), col.green(), col.blue(), a)
            p.setBrush(QBrush(col2)); p.setPen(Qt.PenStyle.NoPen)
            p.drawEllipse(int(cx + x - dot_r), int(cy + y - dot_r), int(dot_r * 2), int(dot_r * 2))
            # Faint orbit path (only draw once per sphere pass, thin)
            if i == 0:
                pen2 = QPen(QColor(0, 240, 255, 26)); pen2.setWidthF(0.6); p.setPen(pen2); p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawEllipse(int(cx - sat_r), int(cy - sat_r * math.cos(tilt)), int(sat_r * 2), int(sat_r * 2 * math.cos(tilt)))


class _Gauge(QWidget):
    """Arc donut gauge — track + progress arc + centered number + visible
    label BELOW the arc. Label was clipped in the old version; widget is
    now taller and label uses a larger legible font."""
    def __init__(self, size=64, radius=26, label='CORE', accent='#00f0ff', init_pct=0, mode='pct', parent=None):
        super().__init__(parent)
        # Layout: 18px TITLE strip (bold, always-visible pill) → arc below.
        # Title above avoids the "invisible label" bug users hit when the
        # header row clipped anything painted underneath the arc.
        self._title_h = 18
        self.setFixedSize(size, size + self._title_h + 2)
        self._sz = size; self._r = radius
        self._lbl = label; self._accent = QColor(accent) if isinstance(accent, str) else accent
        self._pct = init_pct
        self._mode = mode
        self._value = init_pct

    def set_value(self, v, pct=None):
        self._value = v
        if pct is not None:
            self._pct = max(0, min(100, pct))
        else:
            self._pct = max(0, min(100, int(v)))
        self.update()

    def paintEvent(self, ev):
        import math
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        # === TITLE PILL — ABOVE arc, always-visible ===
        t_h = self._title_h
        t_x = 0; t_y = 0; t_w = self._sz
        pill_bg = QColor(self._accent); pill_bg.setAlpha(70)
        p.setPen(Qt.PenStyle.NoPen); p.setBrush(QBrush(pill_bg))
        p.drawRoundedRect(t_x, t_y, t_w, t_h, 5, 5)
        pill_bd = QColor(self._accent); pill_bd.setAlpha(220)
        p.setPen(QPen(pill_bd, 1)); p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawRoundedRect(t_x, t_y, t_w - 1, t_h - 1, 5, 5)
        p.setPen(QColor(255, 255, 255, 250))
        f_t = self.font(); f_t.setBold(True); f_t.setPointSize(8)
        f_t.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, 1)
        p.setFont(f_t)
        p.drawText(t_x, t_y, t_w, t_h, Qt.AlignmentFlag.AlignCenter, self._lbl)
        # === ARC ===
        arc_top = t_h + 2
        cx = self._sz / 2; cy = arc_top + self._sz / 2
        r = self._r
        pen = QPen(QColor(0, 240, 255, 40)); pen.setWidth(4); p.setPen(pen)
        p.drawArc(int(cx - r), int(cy - r), int(r * 2), int(r * 2), 0, 360 * 16)
        pen2 = QPen(self._accent); pen2.setWidth(4); pen2.setCapStyle(Qt.PenCapStyle.RoundCap); p.setPen(pen2)
        span = int(-360 * (self._pct / 100.0) * 16)
        p.drawArc(int(cx - r), int(cy - r), int(r * 2), int(r * 2), 90 * 16, span)
        # Centered number — bigger + accent-tinted for hardware gauges
        p.setPen(QColor(255, 255, 255))
        f = self.font(); f.setBold(True); f.setPointSize(13); p.setFont(f)
        num = f'{self._value}%' if self._mode == 'pct' else str(self._value)
        p.drawText(0, int(cy - 12), self._sz, 24, Qt.AlignmentFlag.AlignCenter, num)


# Separate _SatelliteBurst + _TremorRipple removed — they spawned N frameless
# toplevel windows per hit which killed compute. Ripple + satellites now
