def _bm23_tg_install(mw):
    import subprocess, sys as _sys, importlib.util as _ilu
    from pathlib import Path as _P
    from PyQt6.QtWidgets import (QDialog, QVBoxLayout, QHBoxLayout, QPushButton,
                                  QPlainTextEdit, QLabel, QMessageBox, QCheckBox,
                                  QSpinBox)
    from PyQt6.QtCore import QTimer as _QT, Qt as _Qt
    from PyQt6.QtGui import QAction as _QA

    HERE = _P(__file__).resolve().parent
    BASE_DIR = _P.home() / '.email_archive'
    BASE_DIR.mkdir(parents=True, exist_ok=True)
    MOD = HERE / 'bm23_tg_ingest.py'
    LOG = _P.home() / '.email_archive' / 'tg_ingest.log'
    CFG = _P.home() / '.email_archive' / 'tg_ingest.json'
    PREFS = _P.home() / '.email_archive' / 'tg_ingest_ui.json'

    def _load_ingest_mod():
        try:
            import asyncio, threading
            if threading.current_thread() is threading.main_thread():
                try:
                    loop = asyncio.get_event_loop()
                    if not loop.is_running():
                        asyncio.set_event_loop(asyncio.new_event_loop())
                except RuntimeError:
                    asyncio.set_event_loop(asyncio.new_event_loop())
            _sys.modules.pop('bm23_tg_ingest', None)
            spec = _ilu.spec_from_file_location('bm23_tg_ingest', str(MOD))
            m = _ilu.module_from_spec(spec)
            _sys.modules['bm23_tg_ingest'] = m
            spec.loader.exec_module(m)
            return m
        except Exception:
            try:
                _sys.modules.pop('bm23_tg_ingest', None)
                code = MOD.read_text(encoding='utf-8')
                ns = {'__name__': 'bm23_tg_ingest', '__file__': str(MOD), '__builtins__': __builtins__}
                exec(compile(code, str(MOD), 'exec'), ns)
                m = type(sys)('bm23_tg_ingest')
                m.__dict__.update(ns)
                _sys.modules['bm23_tg_ingest'] = m
                if not hasattr(m, 'unprocessed_events'):
                    m.unprocessed_events = lambda limit=25: []
                if not hasattr(m, 'mark_processed'):
                    m.mark_processed = lambda row_id: None
                return m
            except Exception as _e2:
                print(f'[TG] mod import failed: {_e2}', flush=True)
                return None
    _mod = _load_ingest_mod()

    def _load_prefs():
        try:
            if PREFS.exists():
                return __import__('json').loads(PREFS.read_text(encoding='utf-8'))
        except Exception: pass
        return {'auto_mode': False, 'heartbeat_seconds': 45, 'active': False}
    def _save_prefs(p):
        try: PREFS.write_text(__import__('json').dumps(p), encoding='utf-8')
        except Exception: pass
    prefs = _load_prefs()
    state = {'proc_run': None}

    def _proc_alive(p): return p is not None and p.poll() is None
    def _spawn(cmd_arg):
        if not MOD.exists():
            QMessageBox.critical(mw, 'TG INGEST',
                f'Module missing:\n{MOD}\n\nDrop bm23_tg_ingest.py next to SIFT-STABLE.py.')
            return None
        flags = getattr(subprocess, 'CREATE_NO_WINDOW', 0) if _sys.platform == 'win32' else 0
        return subprocess.Popen([_sys.executable, str(MOD), cmd_arg],
                                creationflags=flags, cwd=str(HERE))

    def _sift_running():
        try:
            w = getattr(mw, 'worker', None)
            return bool(w and w.isRunning())
        except Exception: return False
    def _sift_input_edit():
        return getattr(mw, 'input_box', None) or getattr(mw, 'input_edit', None)
    def _sift_start_button():
        return getattr(mw, 'btn_init', None) or getattr(mw, 'btn_start', None)

    def _feed_combos(combos, autofire):
        if not combos: return
        ie = _sift_input_edit()
        if ie is None:
            print('[TG] SIFT input widget not found', flush=True); return
        try:
            existing = ie.toPlainText() if hasattr(ie, 'toPlainText') else ie.text()
        except Exception: existing = ''
        text = existing.rstrip() + ('\n' if existing.strip() else '') + '\n'.join(combos) + '\n'
        try:
            if hasattr(ie, 'setPlainText'): ie.setPlainText(text)
            else: ie.setText(text)
        except Exception as e:
            print(f'[TG] feed failed: {e}', flush=True); return
        if autofire and not _sift_running():
            btn = _sift_start_button()
            if btn is not None and btn.isEnabled():
                try:
                    btn.click()
                    print(f'[TG] auto-INITIATE fired with {len(combos)} combos', flush=True)
                except Exception as e:
                    print(f'[TG] autofire failed: {e}', flush=True)

    def _manual_popup(evt):
        d = QDialog(mw); d.setWindowTitle('TG · NEW HIT')
        d.setWindowFlag(_Qt.WindowType.WindowStaysOnTopHint, True)
        d.resize(640, 320)
        v = QVBoxLayout(d); v.setContentsMargins(14, 14, 14, 14); v.setSpacing(8)
        title = QLabel('⚡  <b>TELEGRAM MATCH</b>'); title.setStyleSheet('font-size:14pt;')
        v.addWidget(title)
        meta = QLabel(
            f'<b>Chat:</b> {evt.get("chat_name","?")}<br>'
            f'<b>File:</b> {evt.get("file_name","?")} <i>({evt.get("file_kind","?")})</i><br>'
            f'<b>Keywords:</b> {", ".join(evt.get("matched_kws", []))}<br>'
            f'<b>Combos:</b> {evt.get("combo_count", 0)}<br>'
            f'<b>Caption:</b> {(evt.get("caption") or "")[:200]}')
        meta.setWordWrap(True); v.addWidget(meta)
        preview = QPlainTextEdit(); preview.setReadOnly(True)
        preview.setPlainText('\n'.join((evt.get('combos') or [])[:15]) or '(no combos extracted)')
        preview.setStyleSheet('font-family: Consolas; font-size: 10px;')
        v.addWidget(preview, 1)
        row = QHBoxLayout()
        b_load = QPushButton('▶  LOAD NOW  (feed into SIFT)')
        b_skip = QPushButton('SKIP')
        row.addWidget(b_load); row.addWidget(b_skip); v.addLayout(row)
        def _load():
            _feed_combos(evt.get('combos') or [], autofire=True)
            if _mod is not None:
                try: _mod.mark_processed(evt['id'])
                except Exception: pass
            d.accept()
        def _skip():
            if _mod is not None:
                try: _mod.mark_processed(evt['id'])
                except Exception: pass
            d.reject()
        b_load.clicked.connect(_load); b_skip.clicked.connect(_skip); d.show()

    # ---- AU-only detector + persistent list ------------------------------
    _AU_LIST_PATH = _P.home() / '.email_archive' / 'au_only.txt'
    def _has_au(combos):
        for c in combos:
            try:
                em = c[0] if isinstance(c, (list, tuple)) and c else str(c)
                if '.com.au' in str(em).lower():
                    return True
            except Exception: pass
        return False
    def _extract_au(combos):
        out = []
        for c in combos:
            try:
                em = c[0] if isinstance(c, (list, tuple)) and c else str(c)
                if '.com.au' in str(em).lower():
                    out.append(c)
            except Exception: pass
        return out
    def _append_au(evt, au_combos):
        try:
            _AU_LIST_PATH.parent.mkdir(parents=True, exist_ok=True)
            with _AU_LIST_PATH.open('a', encoding='utf-8') as fh:
                fh.write(f'\n# {evt.get("chat_name","?")}  ·  {evt.get("file_name","?")}  ·  ts={evt.get("ts","")}\n')
                for c in au_combos:
                    line = c if isinstance(c, str) else (':'.join(str(x) for x in c) if isinstance(c, (list, tuple)) else str(c))
                    fh.write(line + '\n')
        except Exception as e:
            print(f'[TG.au] append fail: {e}', flush=True)

    def _relative_age(ts_epoch):
        # "3h ago" / "12m ago" / "2d ago" — matches Telegram's own format
        try:
            import time as _t
            delta = int(_t.time()) - int(ts_epoch or 0)
            if delta < 60:   return f'{delta}s ago'
            if delta < 3600: return f'{delta // 60}m ago'
            if delta < 86400: return f'{delta // 3600}h ago'
            return f'{delta // 86400}d ago'
        except Exception:
            return '?'

    def _show_tg_hit_popup(evt, combos, au_hit):
        # Rich, styled popup. Manual mode = APPROVE / REJECT gate before
        # combos feed the checker. AU hit = gold border + siren tone,
        # auto-approve regardless of manual flag (still shows for viz).
        from PyQt6.QtWidgets import QDialog, QVBoxLayout, QHBoxLayout, QLabel, QPushButton
        d = QDialog(mw)
        d.setWindowTitle('TG HIT · ' + ('AU PRIORITY · ' if au_hit else '') + evt.get('chat_name', '?'))
        d.resize(520, 340)
        _accent = '#ffd54f' if au_hit else '#00d4ff'
        _bord = '2px solid ' + _accent
        d.setStyleSheet(f"QDialog {{ background:#0a0d14; color:#eaf6ff; border:{_bord}; }} "
                        f"QLabel {{ color:#eaf6ff; font-family:Consolas; }} "
                        f"QPushButton {{ background:qlineargradient(x1:0,y1:0,x2:0,y2:1,"
                        f"stop:0 rgba(0,150,220,0.85), stop:1 rgba(0,60,120,0.85)); "
                        f"color:#eaf6ff; border:1px solid {_accent}; border-radius:6px; "
                        f"padding:10px 24px; font-family:'Segoe UI'; font-size:12px; "
                        f"font-weight:700; letter-spacing:2px; }} "
                        f"QPushButton:hover {{ background:{_accent}; color:#0a0d14; }}")
        v = QVBoxLayout(d); v.setContentsMargins(18, 14, 18, 14); v.setSpacing(10)
        # Header
        _hdr = QLabel(('🚨 AU PRIORITY HIT' if au_hit else '📥 TG HIT'))
        _hdr.setStyleSheet(f"font-size:20px; font-weight:900; color:{_accent}; letter-spacing:3px;")
        v.addWidget(_hdr)
        # File + chat
        v.addWidget(QLabel(f"<b style='color:{_accent}'>FILE</b>    {evt.get('file_name','?')}"))
        v.addWidget(QLabel(f"<b style='color:{_accent}'>CHAT</b>    {evt.get('chat_name','?')}"))
        v.addWidget(QLabel(f"<b style='color:{_accent}'>WHEN</b>    {_relative_age(evt.get('ts'))}"))
        v.addWidget(QLabel(f"<b style='color:{_accent}'>KWS</b>     {', '.join(evt.get('matched_kws', []))}"))
        v.addWidget(QLabel(f"<b style='color:{_accent}'>COMBOS</b>  {len(combos)} total" +
                            (f"   ·   <span style='color:#ffd54f'>{sum(1 for c in combos if _has_au([c]))} AU</span>" if au_hit else '')))
        v.addStretch(1)
        row = QHBoxLayout()
        b_approve = QPushButton('✓ APPROVE + FEED')
        b_reject  = QPushButton('✗ SKIP')
        row.addStretch(1); row.addWidget(b_reject); row.addWidget(b_approve)
        v.addLayout(row)
        result = {'approved': False}
        def _yes(): result['approved'] = True; d.accept()
        def _no():  result['approved'] = False; d.accept()
        b_approve.clicked.connect(_yes); b_reject.clicked.connect(_no)
        # AU hit siren beep (Windows)
        if au_hit:
            try:
                import winsound as _ws
                _ws.Beep(1200, 90); _ws.Beep(800, 90); _ws.Beep(1400, 130)
            except Exception: pass
        d.exec()
        return result['approved']

    heartbeat = _QT(mw)
    def _consume():
        if _mod is None or not prefs.get('active'): return
        try: rows = _mod.unprocessed_events(limit=25)
        except Exception as e:
            print(f'[TG] consume err: {e}', flush=True); return
        if not rows: return
        for evt in rows:
            combos = evt.get('combos') or []
            if not combos:
                try: _mod.mark_processed(evt['id'])
                except Exception: pass
                continue
            au_hit = _has_au(combos)
            # AU: instant persist to au_only.txt regardless of approve flag
            if au_hit:
                _append_au(evt, _extract_au(combos))
                print(f'[TG.au] persisted {len(_extract_au(combos))} AU combo(s) from {evt.get("file_name","?")}', flush=True)
            # Popup gate: manual_approve mode OR au_hit always visualizes
            approved = True
            if prefs.get('manual_approve', False) or au_hit:
                try:
                    approved = _show_tg_hit_popup(evt, combos, au_hit)
                except Exception as e:
                    print(f'[TG] popup err: {e}', flush=True)
                    approved = True   # never lose data on UI crash
            if approved:
                _feed_combos(combos, autofire=True)
            try: _mod.mark_processed(evt['id'])
            except Exception: pass
    heartbeat.timeout.connect(_consume)

    def _dialog():
        # All-in-app wizard: install deps, edit config, guided login, run.
        # No shell required.
        from PyQt6.QtWidgets import (QDialog, QVBoxLayout, QHBoxLayout, QGroupBox,
                                      QGridLayout, QLabel, QLineEdit, QSpinBox,
                                      QPlainTextEdit, QPushButton, QMessageBox,
                                      QInputDialog, QCheckBox, QApplication)
        from PyQt6.QtCore import QProcess
        d = QDialog(mw); d.setWindowTitle('BM23 · TG INGEST · Setup + Control'); d.resize(1000, 780)
        v = QVBoxLayout(d); v.setContentsMargins(12, 12, 12, 12); v.setSpacing(8)
        info = QLabel(
            f'<b>Config file:</b> <code>{CFG}</code><br>'
            f'<b>Log file:</b> <code>{LOG}</code>')
        info.setWordWrap(True); v.addWidget(info)

        # ---- Load existing config into UI or defaults ----
        def _read_cfg_or_default():
            import json as _j
            if CFG.exists():
                try:
                    return _j.loads(CFG.read_text(encoding='utf-8'))
                except Exception: pass
            return {
                'api_id': 0, 'api_hash': '', 'session_name': 'tg_ingest',
                'watch_chats': [], 'keywords': ['hot','fresh','mix','mail','australia','AU'],
                'heartbeat_seconds': 45, 'only_txt_rar': True,
                'max_stream_bytes': 25 * 1024 * 1024,
                'forward_to': '', 'catchup_limit_first_run': 5,
            }
        cur = _read_cfg_or_default()

        # ==== PROFILE SELECTOR (multi-account) ====
        from PyQt6.QtWidgets import QComboBox
        gb_prof = QGroupBox('Telegram profile (add multiple accounts here)')
        gpr = QHBoxLayout(gb_prof)
        gpr.addWidget(QLabel('Active profile:'))
        cb_prof = QComboBox()
        # Profiles are session files sitting in ~/.email_archive named tg_*.session
        def _list_profiles(_base=BASE_DIR):
            found = []
            for p in sorted(_base.glob('*.session')):
                found.append(p.stem)
            if not found: found = ['tg_ingest']
            return found
        cb_prof.addItems(_list_profiles())
        cur_sess = cur.get('session_name', 'tg_ingest')
        _idx = cb_prof.findText(cur_sess)
        if _idx >= 0: cb_prof.setCurrentIndex(_idx)
        gpr.addWidget(cb_prof, 1)
        b_add_prof = QPushButton('+ NEW ACCOUNT')
        b_del_prof = QPushButton('DELETE THIS PROFILE')
        gpr.addWidget(b_add_prof); gpr.addWidget(b_del_prof)
        v.addWidget(gb_prof)

        def _switch_profile(name):
            # Rewrite config's session_name so next login/run uses this session
            try:
                cfg_now = _read_cfg_or_default()
                cfg_now['session_name'] = name
                CFG.write_text(__import__('json').dumps(cfg_now, indent=2), encoding='utf-8')
            except Exception as _e:
                print(f'[TG] profile switch err: {_e}', flush=True)
        cb_prof.currentTextChanged.connect(_switch_profile)

        def _add_profile():
            name, ok = QInputDialog.getText(d, 'New Telegram profile',
                'Profile name (e.g. "personal", "work"):')
            name = (name or '').strip().replace(' ', '_')
            if not ok or not name: return
            if not name.startswith('tg_'): name = 'tg_' + name
            cb_prof.addItem(name); cb_prof.setCurrentText(name)
            _switch_profile(name)
            QMessageBox.information(d, 'TG INGEST',
                f'Profile "{name}" created. Fill Step 2 credentials for this account, '
                'then Step 3 GUIDED LOGIN with that account\'s phone number.')
        b_add_prof.clicked.connect(_add_profile)

        def _del_profile():
            name = cb_prof.currentText()
            if name == 'tg_ingest':
                QMessageBox.warning(d, 'TG INGEST', 'Default profile can\'t be deleted.'); return
            if QMessageBox.question(d, 'TG INGEST',
                    f'Delete profile "{name}"?\n\nThis wipes the session file — you\'ll need to re-login to use this account again.') != QMessageBox.StandardButton.Yes:
                return
            for suffix in ('.session', '.session-journal'):
                p = BASE_DIR / f'{name}{suffix}'
                if p.exists():
                    try: p.unlink()
                    except Exception: pass
            cb_prof.removeItem(cb_prof.currentIndex())
            _switch_profile(cb_prof.currentText() if cb_prof.count() else 'tg_ingest')
        b_del_prof.clicked.connect(_del_profile)

        # ==== STEP 1: DEPS (with live install log) ====
        gb_deps = QGroupBox('Step 1 · Install Telegram Python packages (one-time, ~30–90 sec)')
        gl_deps = QVBoxLayout(gb_deps)
        top_row = QHBoxLayout()
        lbl_deps = QLabel('checking…'); top_row.addWidget(lbl_deps, 1)
        b_deps = QPushButton('▶ INSTALL DEPS  (pyrogram + tgcrypto + rarfile)')
        top_row.addWidget(b_deps)
        gl_deps.addLayout(top_row)
        pip_log = QPlainTextEdit(); pip_log.setReadOnly(True)
        pip_log.setFixedHeight(120); pip_log.setPlaceholderText('pip output appears here…')
        pip_log.setStyleSheet('font-family: Consolas; font-size: 10px; background: #0b0f16; color: #a8d5ff;')
        gl_deps.addWidget(pip_log)
        v.addWidget(gb_deps)

        def _deps_status():
            try:
                import pyrogram, rarfile  # noqa
                lbl_deps.setText('<b style="color:#3fc76b">✓ deps installed — ready</b>')
                b_deps.setEnabled(False); b_deps.setText('installed ✓')
            except Exception as _e:
                lbl_deps.setText(f'<b style="color:#ff6b6b">✗ missing —</b> click the button →')
                b_deps.setEnabled(True); b_deps.setText('▶ INSTALL DEPS')
        _deps_status()

        def _run_install():
            b_deps.setEnabled(False); b_deps.setText('installing…')
            lbl_deps.setText('running pip — watch log below')
            pip_log.clear()
            proc = QProcess(d)
            proc.setProgram(sys.executable)
            proc.setArguments(['-m', 'pip', 'install', '--user',
                                'pyrogram', 'tgcrypto', 'rarfile'])
            proc.setProcessChannelMode(QProcess.ProcessChannelMode.MergedChannels)
            def _on_pip_output():
                try:
                    data = bytes(proc.readAll()).decode('utf-8', errors='replace')
                    if data:
                        pip_log.appendPlainText(data.rstrip())
                        pip_log.verticalScrollBar().setValue(pip_log.verticalScrollBar().maximum())
                except Exception: pass
            def _done(ec, _es=None):
                _on_pip_output()
                _deps_status()
                if ec == 0:
                    pip_log.appendPlainText('\n[DONE] Dependencies installed. Move on to Step 2.')
                else:
                    pip_log.appendPlainText(f'\n[ERR] pip exited with code {ec}')
            proc.readyRead.connect(_on_pip_output)
            proc.finished.connect(_done)
            proc.start()
        b_deps.clicked.connect(_run_install)

        # ==== STEP 2: CREDENTIALS + CHATS ====
        gb_cfg = QGroupBox('Step 2 · Credentials + Chats')
        gcf = QGridLayout(gb_cfg); gcf.setSpacing(6)
        r = 0
        gcf.addWidget(QLabel('<b>api_id</b>'), r, 0)
        sp_id = QSpinBox(); sp_id.setRange(0, 2 ** 31 - 1); sp_id.setValue(int(cur.get('api_id') or 0))
        gcf.addWidget(sp_id, r, 1)
        gcf.addWidget(QLabel('from <a href="https://my.telegram.org/apps">my.telegram.org/apps</a>'), r, 2); r += 1
        gcf.addWidget(QLabel('<b>api_hash</b>'), r, 0)
        le_hash = QLineEdit(cur.get('api_hash', '')); le_hash.setPlaceholderText('32-char hex')
        gcf.addWidget(le_hash, r, 1, 1, 2); r += 1
        gcf.addWidget(QLabel('<b>watch_chats</b><br><span style="color:#7fc">optional</span>'), r, 0)
        te_chats = QPlainTextEdit('\n'.join(str(x) for x in (cur.get('watch_chats') or [])))
        te_chats.setPlaceholderText(
            'LEAVE EMPTY = sweep ALL chats (mirrors Telegram Files tab).\n'
            'Or restrict to specific ones: @channelname OR numeric id, one per line.')
        te_chats.setFixedHeight(70)
        gcf.addWidget(te_chats, r, 1, 1, 2); r += 1
        gcf.addWidget(QLabel('<b>keywords</b>'), r, 0)
        le_kw = QLineEdit(', '.join(cur.get('keywords', [])))
        le_kw.setPlaceholderText('comma-separated, CASE-SENSITIVE')
        gcf.addWidget(le_kw, r, 1, 1, 2); r += 1
        gcf.addWidget(QLabel('<b>heartbeat</b><br><span style="color:#7fc">seconds between sweeps</span>'), r, 0)
        sp_hb2 = QSpinBox(); sp_hb2.setRange(5, 3600); sp_hb2.setValue(int(cur.get('heartbeat_seconds', 45)))
        sp_hb2.setSuffix(' sec')
        gcf.addWidget(sp_hb2, r, 1)
        gcf.addWidget(QLabel('<b>forward_to</b> (optional)'), r, 2); r += 1
        le_fwd = QLineEdit(cur.get('forward_to', ''))
        le_fwd.setPlaceholderText('@second_account or empty')
        gcf.addWidget(le_fwd, r, 1, 1, 2); r += 1
        cb_txt_rar = QCheckBox('Only .txt and .rar files')
        cb_txt_rar.setChecked(bool(cur.get('only_txt_rar', True)))
        gcf.addWidget(cb_txt_rar, r, 1, 1, 2); r += 1
        cb_today = QCheckBox('Only today onward (skip old files)')
        cb_today.setChecked(bool(cur.get('only_today', True)))
        gcf.addWidget(cb_today, r, 1, 1, 2); r += 1
        # Output directory row
        gcf.addWidget(QLabel('<b>output dir</b><br><span style="color:#7fc">hit combos land here</span>'), r, 0)
        _row_out = QHBoxLayout()
        le_out = QLineEdit(cur.get('output_dir', '') or str(_P.home() / '.email_archive' / 'tg_hits'))
        _row_out.addWidget(le_out, 1)
        b_pick = QPushButton('BROWSE…')
        _row_out.addWidget(b_pick)
        _out_widget = QWidget(); _out_widget.setLayout(_row_out)
        gcf.addWidget(_out_widget, r, 1, 1, 2); r += 1
        def _pick_out():
            from PyQt6.QtWidgets import QFileDialog
            start = le_out.text().strip() or str(_P.home())
            picked = QFileDialog.getExistingDirectory(d, 'Pick output folder for TG hits', start)
            if picked: le_out.setText(picked)
        b_pick.clicked.connect(_pick_out)
        b_save = QPushButton('💾 SAVE CONFIG')
        gcf.addWidget(b_save, r, 1)
        lbl_saved = QLabel(''); gcf.addWidget(lbl_saved, r, 2); r += 1
        v.addWidget(gb_cfg)

        def _save_cfg():
            import json as _j
            payload = {
                'api_id': int(sp_id.value()),
                'api_hash': le_hash.text().strip(),
                'session_name': 'tg_ingest',
                'watch_chats': [ln.strip() for ln in te_chats.toPlainText().splitlines() if ln.strip()],
                'keywords': [k.strip() for k in le_kw.text().split(',') if k.strip()],
                'heartbeat_seconds': int(sp_hb2.value()),
                'only_txt_rar': cb_txt_rar.isChecked(),
                'only_today': cb_today.isChecked(),
                'output_dir': le_out.text().strip(),
                'max_stream_bytes': 25 * 1024 * 1024,
                'forward_to': le_fwd.text().strip(),
                'catchup_limit_first_run': 5,
            }
            try:
                CFG.parent.mkdir(parents=True, exist_ok=True)
                CFG.write_text(_j.dumps(payload, indent=2), encoding='utf-8')
                lbl_saved.setText('<span style="color:#3fc76b">saved</span>')
            except Exception as _e:
                lbl_saved.setText(f'<span style="color:#ff6b6b">err: {_e}</span>')
        b_save.clicked.connect(_save_cfg)

        # ==== STEP 3: GUIDED LOGIN ====
        gb_lgn = QGroupBox('Step 3 · Guided login (in-app phone + code)')
        gl_lgn = QHBoxLayout(gb_lgn)
        lbl_lgn = QLabel('not yet logged in')
        gl_lgn.addWidget(lbl_lgn, 1)
        b_lgn = QPushButton('🔑 GUIDED LOGIN')
        gl_lgn.addWidget(b_lgn)
        v.addWidget(gb_lgn)

        # In-process pyrogram login via QThread. Kills the CMD popup and
        # subprocess-crash cascade the old QProcess approach caused.
        from PyQt6.QtCore import QThread, pyqtSignal as _psig, QMutex, QWaitCondition

        class _TGLoginWorker(QThread):
            need_phone = _psig()
            need_confirm = _psig(str)
            need_code = _psig()
            need_password = _psig()
            log_line = _psig(str)
            done_ok = _psig(bool, str)   # ok, message

            def __init__(self, api_id, api_hash, session_name, workdir):
                super().__init__()
                self.api_id = int(api_id)
                self.api_hash = str(api_hash)
                self.session_name = str(session_name)
                self.workdir = str(workdir)
                self.phone = None
                self.confirm_ok = False
                self.code = None
                self.password = None
                self._mtx = QMutex()
                self._cond = QWaitCondition()

            def provide(self, key, val):
                self._mtx.lock()
                setattr(self, key, val)
                self._cond.wakeAll()
                self._mtx.unlock()

            def _wait_for(self, attr):
                self._mtx.lock()
                while getattr(self, attr) is None:
                    self._cond.wait(self._mtx, 500)
                self._mtx.unlock()

            def run(self):
                import asyncio
                try:
                    asyncio.new_event_loop().run_until_complete(self._async_login())
                except Exception as e:
                    self.done_ok.emit(False, f'login exception: {e}')

            async def _async_login(self):
                try:
                    from pyrogram import Client
                    from pyrogram.errors import SessionPasswordNeeded, PhoneCodeInvalid, PhoneNumberInvalid
                except Exception as e:
                    self.done_ok.emit(False, f'pyrogram import failed: {e}')
                    return
                try:
                    client = Client(name=self.session_name, api_id=self.api_id,
                                     api_hash=self.api_hash, workdir=self.workdir,
                                     app_version='SIFT-TG-Ingest/1.1',
                                     device_model='BM23-Toolz',
                                     system_version='Windows')
                    self.log_line.emit('connecting…')
                    await client.connect()
                    # Ask phone
                    self.need_phone.emit()
                    self._wait_for('phone')
                    self.log_line.emit(f'sending code to {self.phone}…')
                    sent = await client.send_code(self.phone)
                    # Ask code
                    self.need_code.emit()
                    self._wait_for('code')
                    try:
                        await client.sign_in(self.phone, sent.phone_code_hash, self.code)
                    except SessionPasswordNeeded:
                        self.need_password.emit()
                        self._wait_for('password')
                        await client.check_password(self.password)
                    me = await client.get_me()
                    # Force session flush BEFORE disconnect — pyrogram v2 only
                    # commits the auth key to disk on storage.save(). Without
                    # this, the .session file exists but has no login state
                    # and the next run re-prompts for phone/code.
                    try:
                        await client.storage.save()
                    except Exception: pass
                    await client.disconnect()
                    # Sanity check on disk
                    sess_path = Path(self.workdir) / f'{self.session_name}.session'
                    disk_ok = sess_path.exists() and sess_path.stat().st_size > 1024
                    self.done_ok.emit(True,
                        f'signed in as @{me.username or "?"} (id={me.id})  ·  '
                        f'session {"saved" if disk_ok else "NOT saved to disk"} ({sess_path.name})')
                except PhoneNumberInvalid:
                    self.done_ok.emit(False, 'phone number invalid — try again')
                except PhoneCodeInvalid:
                    self.done_ok.emit(False, 'confirmation code invalid')
                except Exception as e:
                    self.done_ok.emit(False, f'login error: {e}')

        def _run_login():
            if sp_id.value() == 0 or not le_hash.text().strip():
                QMessageBox.warning(d, 'TG INGEST', 'Fill api_id + api_hash first (Step 2).'); return
            _save_cfg()
            # Verify deps present in-process
            try:
                import pyrogram  # noqa
            except Exception as _e:
                QMessageBox.warning(d, 'TG INGEST',
                    f'pyrogram not installed — run Step 1 INSTALL DEPS first.\n\n{_e}')
                return
            b_lgn.setEnabled(False); lbl_lgn.setText('connecting to Telegram…')
            session_name = cb_prof.currentText() if cb_prof.count() else 'tg_ingest'
            worker = _TGLoginWorker(int(sp_id.value()), le_hash.text().strip(),
                                     session_name, str(BASE_DIR))
            d._bm23_login_worker = worker   # retain to prevent GC
            def _on_phone():
                phone, ok = QInputDialog.getText(d, 'Telegram login',
                    'Enter phone number (international format, e.g. +614XXXXXXXX):')
                if ok and phone.strip():
                    worker.provide('phone', phone.strip())
                else:
                    worker.provide('phone', '')
            def _on_code():
                code, ok = QInputDialog.getText(d, 'Telegram login',
                    'Enter the confirmation code Telegram sent you\n'
                    '(check the Telegram app on any device you\'re logged in on):')
                worker.provide('code', code.strip() if ok else '')
            def _on_pw():
                pw, ok = QInputDialog.getText(d, 'Telegram login',
                    'Enter your 2FA password:', QLineEdit.EchoMode.Password)
                worker.provide('password', pw if ok else '')
            def _on_log(msg):
                lbl_lgn.setText(msg[:200])
            def _on_done(ok, msg):
                b_lgn.setEnabled(True)
                if ok:
                    lbl_lgn.setText(f'<b style="color:#3fc76b">✓ {msg}</b>')
                    b_lgn.setText('logged in — click again to re-login')
                else:
                    lbl_lgn.setText(f'<b style="color:#ff6b6b">✗ {msg}</b>')
            worker.need_phone.connect(_on_phone)
            worker.need_code.connect(_on_code)
            worker.need_password.connect(_on_pw)
            worker.log_line.connect(_on_log)
            worker.done_ok.connect(_on_done)
            worker.start()
        b_lgn.clicked.connect(_run_login)

        # ==== STEP 4: RUN ====
        gb_run = QGroupBox('Step 4 · Run')
        gr = QVBoxLayout(gb_run)
        opts = QHBoxLayout()
        cb_auto = QCheckBox('AUTO MODE (feed hits straight into SIFT)')
        cb_auto.setChecked(bool(prefs.get('auto_mode')))
        opts.addWidget(cb_auto)
        cb_manual = QCheckBox('MANUAL APPROVE (popup each hit before feed)')
        cb_manual.setChecked(bool(prefs.get('manual_approve')))
        cb_manual.setToolTip('When on, every TG hit shows a popup with file/time/kw/combo-count. '
                              'APPROVE feeds combos; SKIP drops them. AU (.com.au) hits always show popup + auto-save to au_only.txt.')
        opts.addWidget(cb_manual)
        opts.addStretch(1)
        opts.addWidget(QLabel('SIFT-side consumer heartbeat (seconds):'))
        sp_hb = QSpinBox(); sp_hb.setRange(5, 3600)
        sp_hb.setValue(int(prefs.get('heartbeat_seconds', 45)))
        sp_hb.setSuffix(' sec')
        opts.addWidget(sp_hb); gr.addLayout(opts)

        row = QHBoxLayout()
        b_run = QPushButton('▶ START POLLER')
        b_stop = QPushButton('■ STOP POLLER')
        b_show = QPushButton('SHOW EVENTS')
        for b in (b_run, b_stop, b_show): row.addWidget(b)
        gr.addLayout(row)
        v.addWidget(gb_run)
        # Old buttons kept as inert stubs so downstream connects don't crash
        b_init = QPushButton(); b_login = QPushButton()

        status = QLabel(''); status.setStyleSheet('font-family: Consolas; color: #559;')
        v.addWidget(status)
        tail = QPlainTextEdit(); tail.setReadOnly(True)
        tail.setStyleSheet('font-family: Consolas; font-size: 11px;')
        v.addWidget(tail, 1)

        def _refresh_status():
            hb_ok = 'ACTIVE' if prefs.get('active') else 'stopped'
            proc = 'running' if _proc_alive(state['proc_run']) else 'off'
            mode = 'AUTO' if prefs.get('auto_mode') else 'manual'
            status.setText(f'heartbeat: {hb_ok}   ·   poller: {proc}   ·   mode: {mode}   ·   hb={prefs["heartbeat_seconds"]}s')
        def _apply_prefs():
            prefs['auto_mode'] = cb_auto.isChecked()
            prefs['manual_approve'] = cb_manual.isChecked()
            prefs['heartbeat_seconds'] = int(sp_hb.value())
            _save_prefs(prefs)
            heartbeat.setInterval(prefs['heartbeat_seconds'] * 1000)
            _refresh_status()
        cb_auto.toggled.connect(lambda _v: _apply_prefs())
        cb_manual.toggled.connect(lambda _v: _apply_prefs())
        sp_hb.valueChanged.connect(lambda _v: _apply_prefs())

        def _init_cfg():
            p = _spawn('init')
            if p:
                try: p.wait(timeout=5)
                except Exception: pass
                QMessageBox.information(mw, 'TG INGEST',
                    f'Config written to:\n{CFG}\n\nFill api_id + api_hash + watch_chats then LOGIN.')
        def _login(): _spawn('login')
        def _run():
            if not CFG.exists():
                QMessageBox.warning(mw, 'TG INGEST', 'No config — click INIT CONFIG first.'); return
            if _proc_alive(state['proc_run']):
                QMessageBox.information(mw, 'TG INGEST', 'Poller already running.'); return
            state['proc_run'] = _spawn('run')
            prefs['active'] = True; _save_prefs(prefs)
            heartbeat.setInterval(int(prefs['heartbeat_seconds']) * 1000)
            heartbeat.start(); _refresh_status()
        def _stop():
            p = state.get('proc_run')
            if _proc_alive(p):
                try: p.terminate()
                except Exception: pass
            state['proc_run'] = None
            prefs['active'] = False; _save_prefs(prefs)
            heartbeat.stop(); _refresh_status()
        def _show(): _spawn('show')
        b_init.clicked.connect(_init_cfg); b_login.clicked.connect(_login)
        b_run.clicked.connect(_run); b_stop.clicked.connect(_stop)
        b_show.clicked.connect(_show)

        def _refresh_tail():
            try:
                if not LOG.exists(): return
                sz = LOG.stat().st_size
                with LOG.open('rb') as f:
                    if sz > 100_000: f.seek(sz - 100_000)
                    data = f.read().decode('utf-8', errors='replace')
                if data and data != tail.toPlainText():
                    tail.setPlainText(data)
                    tail.verticalScrollBar().setValue(tail.verticalScrollBar().maximum())
            except Exception: pass
        t = _QT(d); t.timeout.connect(_refresh_tail); t.start(700)
        _refresh_tail(); _refresh_status()
        d.exec()

    if prefs.get('active'):
        heartbeat.setInterval(int(prefs.get('heartbeat_seconds', 45)) * 1000)
        heartbeat.start()

    # Expose hooks so the persistent right-rail TG panel can drive us
    def _start_poller_hook():
        if not CFG.exists():
            QMessageBox.warning(mw, 'TG INGEST', 'No config — open the panel and click INIT CONFIG.'); return
        if _proc_alive(state['proc_run']):
            return
        state['proc_run'] = _spawn('run')
        prefs['active'] = True; _save_prefs(prefs)
        heartbeat.setInterval(int(prefs['heartbeat_seconds']) * 1000)
        heartbeat.start()
    def _stop_poller_hook():
        p = state.get('proc_run')
        if _proc_alive(p):
            try: p.terminate()
            except Exception: pass
        state['proc_run'] = None
        prefs['active'] = False; _save_prefs(prefs)
        heartbeat.stop()
    mw._bm23_tg_start_poller = _start_poller_hook
    mw._bm23_tg_stop_poller  = _stop_poller_hook
    mw._bm23_tg_open_dialog  = _dialog
    # Right-rail status refresher
    _rail = QTimer(mw)
    def _rail_tick():
        try:
            lbl = getattr(mw, '_tg_panel_status', None)
            if lbl is None: return
            hb = 'ACTIVE' if prefs.get('active') else 'off'
            proc = 'run' if _proc_alive(state['proc_run']) else 'off'
            mode = 'AUTO' if prefs.get('auto_mode') else 'manual'
            # pending count from ingest db
            pend = 0
            if _mod is not None:
                try: pend = len(_mod.unprocessed_events(limit=100))
                except Exception: pass
            lbl.setText(f'poller: {proc}  ·  hb: {hb}  ·  mode: {mode}  ·  queue: {pend}')
        except Exception: pass
    _rail.timeout.connect(_rail_tick); _rail.start(1500); _rail_tick()

    try:
        mb = mw.menuBar()
        m_tg = None
        for act in mb.actions():
            if act.text().replace('&', '').strip().lower() == 'telegram':
                m_tg = act.menu(); break
        if m_tg is None:
            m_tg = mb.addMenu('&Telegram')
        a_open = _QA('Open TG INGEST panel…', mw)
        a_open.setShortcut('Ctrl+G')
        a_open.triggered.connect(_dialog)
        m_tg.addAction(a_open)
    except Exception as e:
        print(f'[TG] menu install err: {e}', flush=True)


_bm23_orig_main = main
def main():  # type: ignore
    from PyQt6.QtWidgets import QApplication
    from PyQt6.QtCore import QTimer
    def _installer():
        app = QApplication.instance()
        if app is None:
            QTimer.singleShot(400, _installer); return
        for w in app.topLevelWidgets():
            cn = type(w).__name__
            if 'MainWindow' in cn and cn.startswith('_'):
                try: _bm23_tg_install(w)
                except Exception as e: print(f'[TG] install err: {e}', flush=True)
                return
        QTimer.singleShot(500, _installer)
    QTimer.singleShot(800, _installer)
    _bm23_orig_main()


if __name__ == '__main__':
    main()